var COURSES_DB = {};
COURSES_DB['computer-literacy'] = {"id":"computer-literacy","title":"Computer Literacy: From Zero to Confident Digital User","shortDesc":"For complete beginners, learn to use a computer confidently, navigate the internet safely, master Word, Excel, and PowerPoint, and gain the digital skills every Liberian employer expects.","category":"Computer Fundamentals","icon":"💻","image":"complit-banner.jpg","cardImage":"complit-card.jpg","gradient":"linear-gradient(135deg,#1e3a5f,#002868)","instructor":"Samuel Tolbert","instructorTitle":"Founder & CEO, Tolbert Innovation Hub","instructorBio":"Samuel Tolbert founded TIH to bring world-class digital education to Liberia and West Africa. He has trained over 10,000 students across the region in foundational technology skills.","rating":4.9,"reviewCount":1247,"students":"8,400+","duration":"34h","level":"Beginner","price":"FREE","origPrice":"$120","isFree":true,"badge":"free","certId":"TIH-2026-CCL-0042","learn":["Navigate Windows and macOS with full confidence","Create, save, and organize files and folders efficiently","Use the internet safely for research, email, and communication","Create professional documents using Microsoft Word","Build spreadsheets and track data with Microsoft Excel","Design compelling presentations with Microsoft PowerPoint","Protect yourself from viruses, phishing, and online scams","Use Gmail, Google Drive, and collaboration tools productively"],"requirements":["No prior computer experience needed, this course starts from zero","Access to a computer or smartphone (Windows, Mac, or Android)","Willingness to practice daily exercises provided in each module"],"about":["Computer literacy is the foundation of every digital opportunity available today. In Liberia and across West Africa, the ability to confidently use a computer separates those who can access global opportunities from those who cannot. This course was designed specifically for our community, starting from the very basics and building up to professional-level digital skills.","You will learn to use a computer from scratch, master the Microsoft Office suite used in every professional environment, and navigate the internet safely. Each lesson is practical, hands-on, and immediately applicable to real jobs, business, and daily life.","Thousands of Liberians have already completed this course and gone on to secure office jobs, start online businesses, and help their families. Whether you are a student, a job seeker, or a professional wanting to upgrade your skills, this free course is your starting point."],"modules":[{"title":"Module 1: Getting Started with Computers","icon":"💻","meta":"5 lessons · 45 min","lessons":[{"t":"1.1 What is a Computer? Hardware vs Software","d":"8:30","v":"NARrnGza4kA"},{"t":"1.2 Navigating Windows: Desktop, Files & Folders","d":"12:00","v":"qIRRiM6Ibno"},{"t":"1.3 Typing Skills & Keyboard Shortcuts","d":"10:00","v":"QTeX0Za2Ur8"},{"t":"1.4 Managing Files: Save, Copy, Move & Delete","d":"9:00","v":"k-EID5_2D9U"},{"t":"📝 Quiz: Computer Basics","d":"10 questions","isQuiz":true,"quizId":"mod1"}]},{"title":"Module 2: Internet & Digital Communication","icon":"🌐","meta":"5 lessons · 42 min","lessons":[{"t":"2.1 How the Internet Works & Staying Safe Online","d":"10:00","v":"bSBLF66cCN0"},{"t":"2.2 Effective Google Search & Evaluating Sources","d":"8:00","v":"iLMUrr0C_0c"},{"t":"2.3 Setting Up & Using Gmail Professionally","d":"9:30","v":"PEB9jEXh0X4"},{"t":"2.4 Google Drive, Docs & Cloud Storage","d":"9:30","v":"NZlemQPeo0Q"},{"t":"📝 Quiz: Internet & Digital Safety","d":"10 questions","isQuiz":true,"quizId":"mod2"}]},{"title":"Module 3: Microsoft Office Productivity","icon":"📄","meta":"5 lessons · 55 min","lessons":[{"t":"3.1 Microsoft Word: Documents, CVs & Letters","d":"12:00","v":"EuWTrvT_YyY"},{"t":"3.2 Microsoft Excel: Spreadsheets & Basic Formulas","d":"14:00","v":"Vl0H-qTclOg"},{"t":"3.3 Microsoft PowerPoint: Creating Presentations","d":"10:00","v":"DzPhjLPLLeg"},{"t":"3.4 Printing, Formatting & Professional Documents","d":"9:00","v":"CBPe_IFxJWc"},{"t":"🛠️ Project: Create a Professional CV & Cover Letter","d":"Project","isProject":true}]},{"title":"Module 4: Digital Safety & Career Readiness","icon":"🏆","meta":"4 lessons · 38 min","lessons":[{"t":"4.1 Cybersecurity Basics: Passwords, Viruses & Scams","d":"10:00","v":"ey4dXseAODE"},{"t":"4.2 Online Job Searching & LinkedIn Basics","d":"9:00","v":"dOZDQpulyCQ"},{"t":"4.3 Digital Payments & Mobile Money Safety","d":"9:30","v":"CQFXF6bbeI8"},{"t":"📝 Quiz: Digital Safety & Career Readiness","d":"10 questions","isQuiz":true,"quizId":"mod4"}]},{"title":"Module 5: Online Collaboration & Remote Work Tools","icon":"🤝","meta":"4 lessons · reading + quiz","lessons":[{"t":"5.1 Video Meetings with Zoom & Google Meet","d":"Video + notes","v":"5kedqr2Ds-E"},{"t":"5.2 Professional Communication: Email Etiquette, WhatsApp Business & Slack","d":"Video + notes","v":"ZeY62YV_6rs"},{"t":"5.3 Digital Organization: Calendars, Scheduling & Task Management","d":"Video + notes","v":"aEJ7QGrJshA"},{"t":"📝 Quiz: Online Collaboration & Remote Work","d":"10 questions","isQuiz":true,"quizId":"mod5"}]},{"title":"Module 6: Capstone, Launching Your Digital Career","icon":"🚀","meta":"4 lessons · capstone + final","lessons":[{"t":"6.1 Building Your Professional Online Presence","d":"Video + notes","v":"YCb2icQuv8Y"},{"t":"6.2 Freelancing & Earning Online from Liberia","d":"Video + notes","v":"KR1WYQEehwc"},{"t":"6.3 Capstone Project: Your Digital Job Application Kit","d":"Video + notes","v":"KfScugUnSSM"},{"t":"🏆 Final Assessment & Certificate","d":"20 questions","isQuiz":true,"quizId":"final","isFinal":true}]}],"reviews":[{"name":"Fatima Kamara","loc":"Monrovia, Liberia","date":"May 2026","bg":"#002868","init":"FK","rating":5,"text":"Before this course I was afraid to touch a computer. Now I use Excel at work every day and my boss is impressed. Samuel explains everything so clearly, no step is skipped. This free course changed my career completely."},{"name":"Joseph Blamo","loc":"Buchanan, Liberia","date":"April 2026","bg":"#E31E24","init":"JB","rating":5,"text":"I took this course after losing my job and needed to upgrade my skills. Within 3 weeks I could type fast, use Word and Excel, and send professional emails. I got a new job offer within a month. TIH is a blessing for Liberia."},{"name":"Mary Kolie","loc":"Gbarnga, Liberia","date":"March 2026","bg":"#10b981","init":"MK","rating":5,"text":"The module on internet safety alone was worth everything. I had already been scammed once online before. This course taught me exactly how to protect myself. Every Liberian should take this, especially our young people."},{"name":"Thomas Sirleaf","loc":"Harper, Maryland County","date":"June 2026","bg":"#7c3aed","init":"TS","rating":4,"text":"Living in Maryland County, I never thought I could access quality tech training. TIH made it possible online. The certificate is verified and I used it on my job application. Very grateful for this free resource."}],"faqs":[{"q":"Is this course really free?","a":"Yes, completely free. TIH believes foundational computer literacy should be accessible to every Liberian regardless of income. No credit card required."},{"q":"Do I need any equipment?","a":"You need access to a computer or smartphone. A computer is recommended for the Microsoft Office modules, but most lessons can be followed on any device."},{"q":"How long does the certificate take?","a":"Most students complete the course in 3-4 weeks studying 1-2 hours per day. Your certificate is issued immediately upon passing the final assessment."},{"q":"Is the certificate recognized by employers?","a":"Yes. TIH certificates include a unique verification code. Over 200 Liberian employers and NGOs recognize TIH certifications for hiring decisions."}]};
COURSES_DB['ai'] = {"id":"ai","title":"AI Fundamentals: ChatGPT, Gemini & Practical AI Tools","shortDesc":"For professionals, students, and entrepreneurs, learn to use ChatGPT, Gemini, and other AI tools to write faster, research smarter, automate tasks, and gain a real competitive edge in your career.","category":"Artificial Intelligence","icon":"🤖","gradient":"linear-gradient(135deg,#7c3aed,#5b21b6)","instructor":"Dr. Mariama Koroma","instructorTitle":"AI Researcher & Digital Education Lead","instructorBio":"Dr. Mariama Koroma holds a PhD in Computer Science with specialization in machine learning and has led AI literacy programs across West Africa. She is passionate about democratizing AI knowledge for African professionals.","rating":4.8,"reviewCount":832,"students":"5,200+","duration":"28h","level":"Beginner","price":"FREE","origPrice":"$150","isFree":true,"badge":"free","certId":"TIH-2026-AI-0088","learn":["Understand how AI and machine learning actually work behind the scenes","Write powerful prompts to get professional results from ChatGPT and Gemini","Use AI to write emails, reports, proposals, and marketing content","Generate images and creative content using AI tools like DALL-E and Canva AI","Automate repetitive business tasks using AI workflows","Critically evaluate AI output and identify hallucinations and errors","Apply AI ethically and responsibly in business and personal use","Build an AI-powered productivity system for your work or business"],"requirements":["Basic computer and internet skills (equivalent to our free Computer Literacy course)","A free ChatGPT or Gemini account (we walk you through setup in lesson 1)","Curiosity and openness to experiment, no coding or technical background needed"],"about":["Artificial Intelligence is transforming every industry in the world, and Africa is no exception. Businesses across Liberia and the continent are beginning to use AI to write content, analyze data, automate customer service, and compete globally. This course puts you ahead of that curve.","You will learn to use the most powerful and accessible AI tools available today: ChatGPT, Gemini, DALL-E, and more. More importantly, you will learn HOW to think about AI, understanding its capabilities, limitations, and how to integrate it responsibly into your work and business.","No technical background is required. Whether you are a business owner, student, marketer, teacher, or professional, this course gives you the practical AI skills that are rapidly becoming essential in every field. Join over 5,000 students who have already taken this step into the future."],"modules":[{"title":"Module 1: Understanding AI & Machine Learning","icon":"🤖","meta":"4 lessons · 38 min","lessons":[{"t":"1.1 What is AI? How Machines Learn from Data","d":"10:00","v":"Yq0QkCxoTHM"},{"t":"1.2 Types of AI: Narrow, Generative & Agentic AI","d":"9:00","v":"xvpeMdAs9pE"},{"t":"1.3 AI Tools Landscape: ChatGPT, Gemini, Claude & More","d":"10:00","v":"1PaJ28oVOAI"},{"t":"📝 Quiz: AI Fundamentals","d":"10 questions","isQuiz":true,"quizId":"mod1"}]},{"title":"Module 2: Working with ChatGPT & Gemini","icon":"💬","meta":"5 lessons · 48 min","lessons":[{"t":"2.1 Prompt Engineering: The Art of Asking AI the Right Way","d":"12:00","v":"mTzZod7cBj4"},{"t":"2.2 ChatGPT for Writing: Emails, Reports & Proposals","d":"11:00","v":"89EPPtzZHxE"},{"t":"2.3 Gemini for Research, Analysis & Summaries","d":"10:00","v":"YPOsbQzAPiI"},{"t":"2.4 Advanced Prompting: Role, Context, Format & Examples","d":"10:00","v":"V2Gmt1fEue4"},{"t":"📝 Quiz: Prompting & AI Tools","d":"10 questions","isQuiz":true,"quizId":"mod2"}]},{"title":"Module 3: AI Creative & Productivity Tools","icon":"🎨","meta":"4 lessons · 42 min","lessons":[{"t":"3.1 AI Image Generation: DALL-E, Midjourney & Canva AI","d":"11:00","v":"qDtif1zxbkY"},{"t":"3.2 AI for Video, Audio & Content Creation","d":"10:00","v":"REqOxDfw914"},{"t":"3.3 Building AI Workflows to Automate Your Work","d":"11:00","v":"OA4UP4O1hz0"},{"t":"🛠️ Project: Build an AI-Powered Content Calendar","d":"Project","isProject":true}]},{"title":"Module 4: AI for Business & Ethics","icon":"🏆","meta":"4 lessons · 36 min","lessons":[{"t":"4.1 AI for Small Business: Customer Service & Marketing","d":"10:00","v":"sAhIne0U1Os"},{"t":"4.2 AI Ethics: Bias, Privacy & Responsible Use","d":"9:00","v":"qpp1G0iEL_c"},{"t":"4.3 The Future of AI: Careers, Opportunities & Risks","d":"8:00","v":"fWuzA77Mvzw"},{"t":"📝 Quiz: AI for Business & Ethics","d":"10 questions","isQuiz":true,"quizId":"mod4"}]},{"title":"Module 5: Advanced AI Skills, Custom Assistants, Data & Automation","icon":"⚙️","meta":"4 lessons · reading + quiz","lessons":[{"t":"5.1 Custom AI Assistants: Custom Instructions, GPTs & Gems","d":"Video + notes","v":"p6Z2d3T-fLM"},{"t":"5.2 AI for Data Analysis & Spreadsheets","d":"Video + notes","v":"MoPIkfscD3A"},{"t":"5.3 Connecting AI Tools: Automation Workflows & AI Agents","d":"Video + notes","v":"cXnPxN06boY"},{"t":"📝 Quiz: Advanced AI Skills & Automation","d":"10 questions","isQuiz":true,"quizId":"mod5"}]},{"title":"Module 6: Capstone, Building Your AI-Powered Career","icon":"🚀","meta":"4 lessons · capstone + final","lessons":[{"t":"6.1 AI Freelancing & Consulting Opportunities in West Africa","d":"Video + notes","v":"-LCkwnpUilI"},{"t":"6.2 Designing an AI Solution for a Real Organization","d":"Video + notes","v":"x9Pl1XM4K7A"},{"t":"6.3 Capstone Project: Your AI Portfolio & Pitch","d":"Video + notes","v":"rGSmG7qp2Eg"},{"t":"🏆 Final Assessment & Certificate","d":"20 questions","isQuiz":true,"quizId":"final","isFinal":true}]}],"reviews":[{"name":"Fatima Kamara","loc":"Monrovia, Liberia","date":"May 2026","bg":"#002868","init":"FK","rating":5,"text":"Dr. Koroma explains AI in a way that finally makes sense to me. I now use ChatGPT every day for my marketing work and it has tripled my output. The prompting module alone is worth ten times the course price."},{"name":"Joseph Blamo","loc":"Buchanan, Liberia","date":"April 2026","bg":"#E31E24","init":"JB","rating":5,"text":"I was skeptical about AI but this course showed me how to use it practically for my business. I now automate my customer emails and social posts with AI. My competitors are still doing everything manually, I have a real advantage."},{"name":"Mary Kolie","loc":"Gbarnga, Liberia","date":"March 2026","bg":"#10b981","init":"MK","rating":5,"text":"The section on AI ethics and hallucinations was eye-opening. I used to trust everything AI said. Now I know how to verify and use AI responsibly. This should be required learning for every professional in Liberia."},{"name":"Thomas Sirleaf","loc":"Harper, Maryland County","date":"June 2026","bg":"#7c3aed","init":"TS","rating":4,"text":"Excellent course on a topic that is shaping the future. The practical projects made everything real, I built an actual AI content system for my organization. Great value for the price, highly recommended."}],"faqs":[{"q":"Do I need coding skills to use AI tools?","a":"Absolutely not. ChatGPT, Gemini, and all the tools in this course are designed for everyday users. If you can type, you can use AI effectively."},{"q":"Are the AI tools covered in this course free?","a":"ChatGPT and Gemini both offer free tiers that are sufficient for this entire course. We will also cover some premium features available at low cost."},{"q":"Will AI take my job?","a":"This course addresses this question directly. The evidence shows AI replaces tasks, not entire jobs, and people who know how to use AI will be far more valuable than those who do not."},{"q":"Is this course updated for the latest AI tools?","a":"Yes. TIH updates this course quarterly to reflect the rapidly evolving AI landscape. Enrolled students receive all updates at no extra charge."}]};
COURSES_DB['data'] = {"id":"data","title":"Data Analysis with Excel, Power BI & Google Sheets","shortDesc":"For analysts and NGO workers, clean, analyze, and visualize data using Excel, Power BI, and Google Sheets, and build a portfolio that proves your skills to employers.","category":"Data Analytics","icon":"📊","gradient":"linear-gradient(135deg,#0d9488,#065f46)","instructor":"Emmanuel Kamara","instructorTitle":"Senior Data Analyst & Business Intelligence Trainer","instructorBio":"Emmanuel Kamara has over 8 years of experience in business intelligence and data analytics, having worked with NGOs, government agencies, and private firms across West Africa. He specializes in making data analysis accessible to non-technical professionals.","rating":4.7,"reviewCount":645,"students":"3,800+","duration":"40h","level":"Intermediate","price":"FREE","origPrice":"$180","isFree":true,"badge":"free","certId":"TIH-2026-DA-0109","learn":["Master essential Excel functions: SUM, VLOOKUP, COUNTIF, SUMIF, and more","Build professional pivot tables to summarize and analyze large datasets","Create stunning interactive dashboards in Power BI from scratch","Use Google Sheets collaboratively for real-time team data analysis","Clean and prepare messy data for accurate analysis","Design charts and visualizations that communicate insights clearly","Apply data storytelling techniques to present findings to stakeholders","Complete real-world business intelligence projects for your portfolio"],"requirements":["Basic computer literacy and comfort using a computer (keyboard and mouse)","Microsoft Excel installed (2016 or later) or access to Google Sheets (free)","Power BI Desktop installed (free download from Microsoft) for BI modules"],"about":["Data is the new oil, and Liberia's businesses, NGOs, and government agencies are sitting on untapped reserves. The ability to collect, analyze, and present data is one of the most in-demand and highest-paid skills in today's job market. This course teaches you that skill from the ground up.","Starting with Excel fundamentals and advancing through pivot tables, dashboards, and Power BI, you will build a complete data analysis toolkit. Every lesson uses real-world African business datasets, sales data, donor reports, health statistics, and more, so you immediately see the practical value.","By the end of this course, you will be able to walk into any organization in Liberia, take their raw spreadsheet data, and transform it into clear, actionable business intelligence. This is a skill that commands respect and higher salaries in every sector."],"modules":[{"title":"Module 1: Excel Fundamentals","icon":"📊","meta":"5 lessons · 52 min","lessons":[{"t":"1.1 Excel Interface, Navigation & Essential Shortcuts","d":"10:00","v":"Nf6S6tUHOXw"},{"t":"1.2 Core Functions: SUM, AVERAGE, COUNT, IF, ROUND","d":"12:00","v":"Yov488pacDc"},{"t":"1.3 Sorting, Filtering & Conditional Formatting","d":"11:00","v":"kIZkNDKllws"},{"t":"1.4 Charts & Basic Visualizations","d":"9:00","v":"sVZiU9QHdB4"},{"t":"📝 Quiz: Excel Fundamentals","d":"10 questions","isQuiz":true,"quizId":"mod1"}]},{"title":"Module 2: Advanced Excel & Pivot Tables","icon":"🔢","meta":"5 lessons · 55 min","lessons":[{"t":"2.1 VLOOKUP, HLOOKUP & the New XLOOKUP","d":"13:00","v":"2s-zPZKERP4"},{"t":"2.2 Pivot Tables: Summarize Thousands of Rows Instantly","d":"14:00","v":"dvbLrwD2SpA"},{"t":"2.3 Advanced Formulas: SUMIF, COUNTIF, INDEX-MATCH","d":"12:00","v":"nGQfc0V3NXk"},{"t":"2.4 Data Validation & Protecting Spreadsheets","d":"9:00","v":"gPHzXAncp5I"},{"t":"📝 Quiz: Advanced Excel & Data Analysis","d":"10 questions","isQuiz":true,"quizId":"mod2"}]},{"title":"Module 3: Power BI & Data Visualization","icon":"📈","meta":"4 lessons · 48 min","lessons":[{"t":"3.1 Introduction to Power BI: Interface & Data Import","d":"12:00","v":"VaOhNqNtGGE"},{"t":"3.2 Building Interactive Dashboards in Power BI","d":"14:00","v":"kp_Mb4E-nig"},{"t":"3.3 DAX Basics: Writing Measures & Calculated Columns","d":"12:00","v":"lGhxfC0_g9c"},{"t":"🛠️ Project: NGO Donor Report Dashboard","d":"Project","isProject":true}]},{"title":"Module 4: Google Sheets Collaboration, Data Storytelling & Portfolio","icon":"🏆","meta":"4 lessons · 44 min","lessons":[{"t":"4.1 Google Sheets for Team Collaboration & Analysis","d":"10:00","v":"cjjAJM1o5E8"},{"t":"4.2 Data Storytelling: Presenting Insights to Decision Makers","d":"11:00","v":"H79S8YDuYUU"},{"t":"4.3 Building Your Data Analysis Portfolio","d":"12:00","v":"n9LNj8IEyQs"},{"t":"📝 Quiz: Google Sheets, Data Storytelling & Portfolio","d":"10 questions","isQuiz":true,"quizId":"mod4"}]},{"title":"Module 5: Data Cleaning & Automation with Power Query","icon":"🧹","meta":"4 lessons · reading + quiz","lessons":[{"t":"5.1 Power Query Basics: Import & Transform Data","d":"Video + notes","v":"QXzopqpHlSs"},{"t":"5.2 Cleaning Messy Real-World Datasets","d":"Video + notes","v":"1gOQYLgGpKA"},{"t":"5.3 Refreshable Reports: Automating Your Monthly Workflow","d":"Video + notes","v":"x7mzOYEn0XA"},{"t":"📝 Quiz: Data Cleaning & Power Query Automation","d":"10 questions","isQuiz":true,"quizId":"mod5"}]},{"title":"Module 6: Capstone, End-to-End Analytics Projects & Your Data Career","icon":"💼","meta":"4 lessons · capstone + final","lessons":[{"t":"6.1 Scoping an Analytics Project with a Real Client","d":"Video + notes","v":"EYd36SJrCrg"},{"t":"6.2 Building the Dashboard: From Raw Data to Decision","d":"Video + notes","v":"9n-_vIAT-GY"},{"t":"6.3 Presenting Your Portfolio & Landing Data Jobs in West Africa","d":"Video + notes","v":"iNaDxZXc_Ao"},{"t":"🏆 Final Assessment & Certificate","d":"20 questions","isQuiz":true,"quizId":"final","isFinal":true}]}],"reviews":[{"name":"Fatima Kamara","loc":"Monrovia, Liberia","date":"May 2026","bg":"#002868","init":"FK","rating":5,"text":"Emmanuel is a fantastic teacher. I went from knowing only basic Excel to building full Power BI dashboards for my NGO. Our donors are impressed with our reporting. This course paid for itself in the first week of applying the skills."},{"name":"Joseph Blamo","loc":"Buchanan, Liberia","date":"April 2026","bg":"#E31E24","init":"JB","rating":5,"text":"The pivot table module alone transformed how I manage our company's sales data. What used to take me two days now takes 20 minutes. The Power BI dashboard I built is now used in our weekly management meetings."},{"name":"Mary Kolie","loc":"Gbarnga, Liberia","date":"March 2026","bg":"#10b981","init":"MK","rating":5,"text":"I work in the health sector and the data skills I learned here have directly improved how we track and report patient outcomes. The course uses real African data examples which makes it immediately relevant to our work."},{"name":"Thomas Sirleaf","loc":"Harper, Maryland County","date":"June 2026","bg":"#7c3aed","init":"TS","rating":4,"text":"Solid, comprehensive course covering everything from basic formulas to Power BI. The difficulty level is well-paced, challenging enough to be valuable but clear enough to follow. I now list Data Analysis on my CV with confidence."}],"faqs":[{"q":"Do I need to buy Microsoft Excel?","a":"You can use the free Google Sheets for most modules. Microsoft Excel 2016+ is recommended but the free 30-day Microsoft trial is sufficient to complete the course."},{"q":"How is this different from the Office course?","a":"The Office course covers Excel basics for general use. This Data course goes much deeper into analytics, advanced functions, pivot tables, and Power BI for professional data work."},{"q":"Will I be able to get a data analyst job after this?","a":"This course builds strong foundational data skills. Combined with practice projects, many graduates have secured data analyst, reporting, and business intelligence roles."},{"q":"Are the datasets used in lessons realistic?","a":"Yes. All practice datasets are modeled on real Liberian and West African business scenarios, NGO reports, retail sales, health data, and government statistics."}]};
COURSES_DB['webdev'] = {"id":"webdev","title":"Web Development: HTML, CSS & JavaScript","shortDesc":"For aspiring developers and entrepreneurs, learn to build real, responsive websites from scratch using HTML5, CSS3, and JavaScript, and graduate with three portfolio projects deployed live online.","category":"Web Development","icon":"🌐","gradient":"linear-gradient(135deg,#0284c7,#0ea5e9)","instructor":"David Weah","instructorTitle":"Full-Stack Web Developer & Tech Lead","instructorBio":"David Weah is a full-stack developer with 9 years building web applications for businesses across Africa and Europe. He has taught web development to over 2,000 students and runs a thriving tech agency in Monrovia.","rating":4.8,"reviewCount":583,"students":"4,300+","duration":"42h","level":"Beginner","price":"FREE","origPrice":"$200","isFree":true,"badge":"free","certId":"TIH-2026-WD-0074","learn":["Write clean, semantic HTML5 to structure any web page","Style beautiful websites using CSS3, Flexbox, and Grid","Build fully responsive layouts that work on mobile, tablet, and desktop","Add interactivity with JavaScript and DOM manipulation","Work with HTML forms, inputs, and data validation","Debug code using browser developer tools","Deploy your website live using GitHub Pages for free","Build a professional portfolio of 3 complete web projects"],"requirements":["No coding or programming experience needed, completely beginner-friendly","A computer with a modern browser (Chrome recommended) and internet connection","VS Code code editor (free, setup instructions provided in lesson 1)"],"about":["Web development is one of the most powerful and portable skills you can learn. Every business, church, school, NGO, and government office needs a website, and people who can build them are always in demand. This course teaches you everything needed to build professional websites from scratch.","You will start from the very basics, how the web works, and progress through HTML structure, CSS styling, responsive design, and JavaScript interactivity. Every lesson builds on the last, and you will be building real projects from lesson one. No reading theory without application.","By the time you earn your certificate, you will have three complete websites in your portfolio: a personal portfolio site, a business landing page, and an interactive web application. Our graduates freelance, join tech companies, and launch their own digital agencies."],"modules":[{"title":"Module 1: HTML5, Structure of the Web","icon":"🌐","meta":"4 lessons · 40 min","lessons":[{"t":"1.1 How the Web Works: Browsers, Servers & HTML","d":"9:00","v":"pfYQz5pnFmo"},{"t":"1.2 HTML Tags, Semantic Structure & Page Layout","d":"11:00","v":"kX3TfdUqpuU"},{"t":"1.3 Forms, Tables, Links, Images & Multimedia","d":"11:30","v":"AJrkz0pzRV4"},{"t":"📝 Quiz: HTML5 Fundamentals","d":"10 questions","isQuiz":true,"quizId":"mod1"}]},{"title":"Module 2: CSS3 & Responsive Design","icon":"🎨","meta":"4 lessons · 46 min","lessons":[{"t":"2.1 CSS Selectors, the Box Model & Typography","d":"11:00","v":"YhoK5y0HgPk"},{"t":"2.2 Flexbox Layouts: Build Any UI Component","d":"12:00","v":"fYq5PXgSsbE"},{"t":"2.3 CSS Grid & Media Queries for Responsive Design","d":"13:00","v":"dT3aujtzBe4"},{"t":"📝 Quiz: CSS3 & Layouts","d":"10 questions","isQuiz":true,"quizId":"mod2"}]},{"title":"Module 3: JavaScript Interactivity","icon":"⚡","meta":"4 lessons · 44 min","lessons":[{"t":"3.1 JavaScript Variables, Functions & Logic","d":"11:00","v":"dJvPTRXyc6s"},{"t":"3.2 DOM Manipulation: Change Pages Dynamically","d":"11:30","v":"5fb2aPlgoys"},{"t":"3.3 Events, Forms & Input Validation","d":"11:30","v":"RjtarcWFc6A"},{"t":"🛠️ Project: Build an Interactive Business Landing Page","d":"Project","isProject":true}]},{"title":"Module 4: Professional Workflows & Deployment","icon":"🏆","meta":"4 lessons · 38 min","lessons":[{"t":"4.1 Git & GitHub: Version Control for Developers","d":"10:00","v":"PWqS4NBhEY8"},{"t":"4.2 Browser DevTools: Debugging & Inspecting Code","d":"9:30","v":"H0XScE08hy8"},{"t":"4.3 Deploy Live with GitHub Pages & Custom Domains","d":"9:00","v":"e5AwNU3Y2es"},{"t":"📝 Quiz: Professional Workflows & Deployment","d":"10 questions","isQuiz":true,"quizId":"mod4"}]},{"title":"Module 5: JavaScript Deep Dive, Data, APIs & Dynamic Apps","icon":"🚀","meta":"4 lessons · reading + quiz","lessons":[{"t":"5.1 Arrays, Objects & Loops: Managing Real Data","d":"Video + notes","v":"orAS-MBh5f4"},{"t":"5.2 Fetch, JSON & Working with Live APIs","d":"Video + notes","v":"ubw2hdQIl4E"},{"t":"5.3 localStorage & Building a Complete Dynamic App","d":"Video + notes","v":"y71CdVq5SvI"},{"t":"📝 Quiz: JavaScript Data, APIs & Dynamic Apps","d":"10 questions","isQuiz":true,"quizId":"mod5"}]},{"title":"Module 6: Capstone, Client Projects, Performance & Your Web Career","icon":"💼","meta":"4 lessons · capstone + final","lessons":[{"t":"6.1 The Client Website Workflow: From Brief to Launch","d":"Video + notes","v":"Jz_wyVdWKm8"},{"t":"6.2 Performance, Accessibility & SEO: Websites That Work for Everyone","d":"Video + notes","v":"AhxvJbG-kSA"},{"t":"6.3 Launching Your Career: Freelancing, Jobs & Growing Beyond This Course","d":"Video + notes","v":"TCgKGPr0trA"},{"t":"🏆 Final Assessment & Certificate","d":"20 questions","isQuiz":true,"quizId":"final","isFinal":true}]}],"reviews":[{"name":"Fatima Kamara","loc":"Monrovia, Liberia","date":"May 2026","bg":"#002868","init":"FK","rating":5,"text":"I built my first website by lesson 3! By the end I had a full portfolio site and 2 paying clients. David makes coding feel natural and achievable. This course is the best investment I have made in my career by far."},{"name":"Joseph Blamo","loc":"Buchanan, Liberia","date":"April 2026","bg":"#E31E24","init":"JB","rating":5,"text":"I was completely terrified of coding before this. Now I build websites for local businesses in Buchanan. The step-by-step approach is perfect for beginners. The JavaScript module was challenging but David explains everything so well."},{"name":"Mary Kolie","loc":"Gbarnga, Liberia","date":"March 2026","bg":"#10b981","init":"MK","rating":5,"text":"The project-based approach made learning stick. By Module 4 I had real work to show employers. I got hired as a junior web developer within 2 months of completing this course. TIH changed my life trajectory completely."},{"name":"Thomas Sirleaf","loc":"Harper, Maryland County","date":"June 2026","bg":"#7c3aed","init":"TS","rating":4,"text":"Excellent comprehensive course. The GitHub and deployment section was especially valuable, I can now deliver live websites to clients. The instructor is very responsive in the discussion forum. Highly recommended."}],"faqs":[{"q":"How hard is coding for a complete beginner?","a":"This course is specifically designed for people who have never coded. We start from zero and progress gradually. Most students are surprised by how quickly they pick it up with the right teaching approach."},{"q":"What tools do I need?","a":"VS Code (free), Chrome browser, and a free GitHub account. All are free and we provide step-by-step setup instructions in the first lesson."},{"q":"Can I get freelance clients after this course?","a":"Many graduates immediately start freelancing. We include a bonus lesson on how to find clients, price your services, and deliver professional websites to Liberian businesses."},{"q":"What should I learn after this course?","a":"We recommend our React & Modern JavaScript course for frontend advancement, or our Full-Stack Development course if you want to build databases and server-side applications."}]};
COURSES_DB['design'] = {"id":"design","title":"Graphic Design with Canva & Adobe Photoshop","shortDesc":"For entrepreneurs and aspiring designers, learn design principles, build brand identities, and create professional graphics in Canva and Photoshop, with an 8-piece portfolio.","category":"Graphic Design","icon":"🎨","gradient":"linear-gradient(135deg,#be185d,#ec4899)","instructor":"Patricia Sumo","instructorTitle":"Creative Director & Brand Design Specialist","instructorBio":"Patricia Sumo is a creative director with over 10 years of design experience working with brands across Liberia, Ghana, and Nigeria. She founded Sumo Creative Studio and has trained hundreds of designers at TIH Academy.","rating":4.6,"reviewCount":634,"students":"2,800+","duration":"30h","level":"Beginner","price":"FREE","origPrice":"$150","isFree":true,"badge":"free","certId":"TIH-2026-GD-0062","learn":["Apply fundamental design principles: layout, color theory, and typography","Create professional logos, flyers, posters, and brand identities in Canva","Master Canva Pro features for high-quality social media and marketing designs","Retouch photos and create composites in Adobe Photoshop","Design a complete brand identity package for a business","Create social media graphics optimized for every platform","Export designs correctly for print and digital use","Build a professional graphic design portfolio"],"requirements":["No design experience needed, all creative skill levels welcome","A computer with internet access for Canva (free browser-based)","Adobe Photoshop (30-day free trial sufficient; link provided in course)"],"about":["Good design is a superpower for business. In Liberia and across Africa, brands that invest in professional visual identity build more trust, attract more customers, and compete more effectively. This course makes professional design accessible to everyone.","Starting with core design principles that never change, you will progress through Canva mastery for everyday design needs, then into Adobe Photoshop for advanced photo editing and creative compositing. Real projects drive every module.","This course is ideal for entrepreneurs building a brand, marketers creating content, professionals wanting to design their own materials, or anyone wanting to start a freelance design career. By graduation you will have a portfolio of 8+ professional design pieces."],"modules":[{"title":"Module 1: Design Principles & Foundations","icon":"🎨","meta":"4 lessons · 36 min","lessons":[{"t":"1.1 Design Principles: Balance, Contrast & Hierarchy","d":"9:30","v":"FpwZTl3dCZE"},{"t":"1.2 Color Theory: Psychology & Palette Creation","d":"10:00","v":"BMDDGuUBO94"},{"t":"1.3 Typography: Fonts, Pairing & Text Design","d":"9:00","v":"HFVTZ7J0W1E"},{"t":"📝 Quiz: Design Principles","d":"10 questions","isQuiz":true,"quizId":"mod1"}]},{"title":"Module 2: Canva, Professional Design Made Easy","icon":"✏️","meta":"4 lessons · 44 min","lessons":[{"t":"2.1 Canva Interface, Templates & Brand Kit Setup","d":"10:00","v":"_ApwkN8BVsc"},{"t":"2.2 Logos, Flyers & Print Materials in Canva","d":"12:00","v":"ZB_LneYCkPU"},{"t":"2.3 Social Media Graphics & Animated Posts","d":"11:00","v":"DSbGwruIcfc"},{"t":"📝 Quiz: Canva Design","d":"10 questions","isQuiz":true,"quizId":"mod2"}]},{"title":"Module 3: Adobe Photoshop Essentials","icon":"🖼️","meta":"4 lessons · 46 min","lessons":[{"t":"3.1 Photoshop Interface & Essential Tools","d":"11:00","v":"OKkWRpoIFuw"},{"t":"3.2 Photo Retouching, Color Correction & Filters","d":"12:00","v":"0jzrqhsXwLo"},{"t":"3.3 Creating Composites & Advanced Selections","d":"12:00","v":"2R5fH8iKAXc"},{"t":"🛠️ Project: Full Brand Identity Package","d":"Project","isProject":true}]},{"title":"Module 4: Professional Design & Portfolio","icon":"🏆","meta":"4 lessons · 36 min","lessons":[{"t":"4.1 Designing for Print: Resolution, Bleed & CMYK","d":"9:30","v":"A4VePn0CAl4"},{"t":"4.2 Designing for Digital: Web, Email & Social Media","d":"9:00","v":"9CnrknQsg5E"},{"t":"4.3 Building & Presenting Your Design Portfolio","d":"9:00","v":"qelg3fYlxAE"},{"t":"📝 Quiz: Print, Digital & Portfolio Skills","d":"10 questions","isQuiz":true,"quizId":"mod4"}]},{"title":"Module 5: Brand Identity & Logo Design Mastery","icon":"🏷️","meta":"4 lessons · reading + quiz","lessons":[{"t":"5.1 The Professional Logo Design Process","d":"Video + notes","v":"DxLR2CFFys0"},{"t":"5.2 Building a Complete Brand Identity System","d":"Video + notes","v":"vaqBJ2dX-Cs"},{"t":"5.3 Mockups & Presenting Brand Work Like a Professional","d":"Video + notes","v":"BSxg87CoOu4"},{"t":"📝 Quiz: Brand Identity & Logo Design","d":"10 questions","isQuiz":true,"quizId":"mod5"}]},{"title":"Module 6: Capstone, The Freelance Design Business","icon":"💼","meta":"4 lessons · capstone + final","lessons":[{"t":"6.1 Winning Clients: Briefs, Pricing & Agreements","d":"Video + notes","v":"t1FdvLveV08"},{"t":"6.2 The Professional Workflow: Feedback, Files & Delivery","d":"Video + notes","v":"fbHP9pF8J2A"},{"t":"6.3 Your Design Career: Portfolio, Platforms & Growth","d":"Video + notes","v":"wHAVsrn4Adc"},{"t":"🏆 Final Assessment & Certificate","d":"20 questions","isQuiz":true,"quizId":"final","isFinal":true}]}],"reviews":[{"name":"Fatima Kamara","loc":"Monrovia, Liberia","date":"May 2026","bg":"#002868","init":"FK","rating":5,"text":"Patricia is an incredible teacher. I came with no design skills and left with a professional portfolio. I now design all my business's social media content myself, saving money on freelancers. This course is worth every penny."},{"name":"Joseph Blamo","loc":"Buchanan, Liberia","date":"April 2026","bg":"#E31E24","init":"JB","rating":4,"text":"The Canva modules are outstanding, I designed a complete brand identity for my shop in week 2. The Photoshop section is advanced but the pace is manageable. Best graphic design training available in Liberia."},{"name":"Mary Kolie","loc":"Gbarnga, Liberia","date":"March 2026","bg":"#10b981","init":"MK","rating":5,"text":"I started freelancing immediately after Module 2. By the end of the course I had 5 paying clients. The brand identity project module gave me a real product to show clients. Patricia's real-world experience shines through every lesson."},{"name":"Thomas Sirleaf","loc":"Harper, Maryland County","date":"June 2026","bg":"#7c3aed","init":"TS","rating":5,"text":"The design principles module fundamentally changed how I see the world. I now notice professional vs amateur design everywhere. The skills from this course have directly improved our church's marketing and outreach materials."}],"faqs":[{"q":"Do I need artistic talent to take this course?","a":"Not at all. Graphic design is a learnable skill. This course teaches you the principles and tools that make design systematic, not just talent-based."},{"q":"Is Canva free?","a":"Canva has a free version that covers most of this course. We also use some Canva Pro features (available free with a 30-day trial). Professional accounts cost about $13/month."},{"q":"Do I need to buy Photoshop?","a":"Adobe Photoshop requires a subscription (about $21/month) but Adobe offers a free 7-30 day trial which is sufficient to complete the course modules."},{"q":"Can I make money with graphic design in Liberia?","a":"Absolutely. Liberian businesses, churches, NGOs, and political campaigns constantly need flyers, social media graphics, and brand identities. Freelance design income is very achievable."}]};
COURSES_DB['android'] = {"id":"android","title":"Android App Development for Beginners","shortDesc":"For aspiring mobile developers, learn Kotlin and Android Studio from scratch, build three complete apps across the modules, and publish your own app on the Google Play Store by the end of the course.","category":"Mobile Development","icon":"📱","gradient":"linear-gradient(135deg,#15803d,#16a34a)","instructor":"Emmanuel Roberts","instructorTitle":"Senior Android Developer & Mobile Tech Educator","instructorBio":"Emmanuel Roberts has 8 years of Android development experience and has published 12 apps on the Google Play Store. He leads TIH's mobile development curriculum and has mentored over 800 app developers across West Africa.","rating":4.7,"reviewCount":421,"students":"1,650+","duration":"40h","level":"Intermediate","price":"FREE","origPrice":"$220","isFree":true,"badge":"free","certId":"TIH-2026-AD-0031","learn":["Set up Android Studio and understand the Android development environment","Write Kotlin code from scratch, variables, functions, classes, and logic","Build Android UI with XML layouts: buttons, text fields, lists, and navigation","Connect your app to the internet and work with APIs and JSON data","Store data locally using SQLite and SharedPreferences","Implement RecyclerView for smooth list and grid displays","Handle user permissions, notifications, and background tasks","Publish your completed app to the Google Play Store"],"requirements":["Basic computer skills and comfort using a computer","A computer with at least 8GB RAM to run Android Studio","No prior programming experience needed, Kotlin basics are taught from scratch"],"about":["Africa has over 600 million smartphone users, and mobile apps are transforming commerce, healthcare, agriculture, and government services across the continent. Learning to build Android apps puts you at the forefront of this transformation.","This course takes a project-first approach, you build a new app in every module, progressively adding features and complexity. By the end, you will have built 3 complete apps and published one live on the Google Play Store.","Whether you want to build apps for your business, start a career as a mobile developer, or create solutions for Liberian communities, this course gives you the complete foundation. No programming experience is required, we start from the absolute beginning with Kotlin."],"modules":[{"title":"Module 1: Android & Kotlin Foundations","icon":"📱","meta":"4 lessons · 44 min","lessons":[{"t":"1.1 Android Ecosystem & Setting Up Android Studio","d":"11:00","v":"2lwmKjkz-DE"},{"t":"1.2 Kotlin Basics: Variables, Types, Functions & Logic","d":"12:00","v":"wCwCsJSCy8Y"},{"t":"1.3 Your First App: Hello Liberia! UI & Activities","d":"12:00","v":"2LWSxWsPUCY"},{"t":"📝 Quiz: Android & Kotlin Foundations","d":"10 questions","isQuiz":true,"quizId":"mod1"}]},{"title":"Module 2: Building Android UIs","icon":"🖼️","meta":"4 lessons · 46 min","lessons":[{"t":"2.1 XML Layouts: Views, Buttons, TextViews & EditTexts","d":"12:00","v":"ISbyj5nFIUk"},{"t":"2.2 Navigation: Multiple Screens & Intent Passing Data","d":"11:30","v":"TwVzuHhQfbk"},{"t":"2.3 RecyclerView: Lists, Grids & Custom Adapters","d":"13:00","v":"Oc4MDMHRzwY"},{"t":"📝 Quiz: Android UI Development","d":"10 questions","isQuiz":true,"quizId":"mod2"}]},{"title":"Module 3: Local Storage, Internet APIs & App Permissions","icon":"🔌","meta":"4 lessons · 48 min","lessons":[{"t":"3.1 Local Data Storage with SharedPreferences & SQLite","d":"12:00","v":"l9ui4Lfgr-E"},{"t":"3.2 Connecting to the Internet: APIs, Retrofit & JSON","d":"13:00","v":"gaPoV4z5wng"},{"t":"3.3 Permissions, Notifications & Background Tasks","d":"12:00","v":"bHlLYhSrXvc"},{"t":"🛠️ Project: Build a News Reader App","d":"Project","isProject":true}]},{"title":"Module 4: Testing, Material Design & Google Play Publishing","icon":"🏆","meta":"4 lessons · 42 min","lessons":[{"t":"4.1 Testing, Debugging & Performance Optimization","d":"11:00","v":"_5LgIrd4O5g"},{"t":"4.2 Material Design: Beautiful, Professional Android UI","d":"10:30","v":"BEvOBTaYUm0"},{"t":"4.3 Publishing Your App to Google Play Store","d":"11:00","v":"WOKrelHPefc"},{"t":"📝 Quiz: Testing, Material Design & Publishing","d":"10 questions","isQuiz":true,"quizId":"mod4"}]},{"title":"Module 5: Modern Android, Jetpack Compose, Architecture & Room","icon":"🧩","meta":"4 lessons · reading + quiz","lessons":[{"t":"5.1 Jetpack Compose: Building UI the Modern Way","d":"Video + notes","v":"l7hGtIzGRRM"},{"t":"5.2 MVVM Architecture & Coroutines: Apps That Scale","d":"Video + notes","v":"EQvLP5BThZ0"},{"t":"5.3 Room Database: Robust Offline Storage","d":"Video + notes","v":"bOd3wO0uFr8"},{"t":"📝 Quiz: Jetpack Compose, Architecture & Room","d":"10 questions","isQuiz":true,"quizId":"mod5"}]},{"title":"Module 6: Capstone, Firebase, Monetization & Your Developer Career","icon":"🚀","meta":"4 lessons · capstone + final","lessons":[{"t":"6.1 Firebase: Adding a Cloud Backend Without a Server","d":"Video + notes","v":"7kzttk9lj3U"},{"t":"6.2 Monetization: Earning From Your Apps in African Markets","d":"Video + notes","v":"ZIWuTgbQiQg"},{"t":"6.3 The Capstone & Your Android Career Path","d":"Video + notes","v":"TrHILjGEEvY"},{"t":"🏆 Final Assessment & Certificate","d":"20 questions","isQuiz":true,"quizId":"final","isFinal":true}]}],"reviews":[{"name":"Fatima Kamara","loc":"Monrovia, Liberia","date":"May 2026","bg":"#002868","init":"FK","rating":5,"text":"I built my first Android app in week 1. By the end of the course I published an app to Google Play that helps Monrovia market vendors list their goods. Emmanuel is an excellent teacher, patient and very knowledgeable."},{"name":"Joseph Blamo","loc":"Buchanan, Liberia","date":"April 2026","bg":"#E31E24","init":"JB","rating":5,"text":"This course is the real deal. The Kotlin fundamentals are taught so clearly I was writing functions on day 2. The API module opened my eyes to what apps can do. I now have a career roadmap that didn't exist before TIH."},{"name":"Mary Kolie","loc":"Gbarnga, Liberia","date":"March 2026","bg":"#10b981","init":"MK","rating":4,"text":"The course is excellent though challenging. The project module is outstanding, building a real news reader app forced me to apply everything I learned. I now feel confident calling myself an Android developer."},{"name":"Thomas Sirleaf","loc":"Harper, Maryland County","date":"June 2026","bg":"#7c3aed","init":"TS","rating":5,"text":"I took this course wanting to build an app for my church. By Module 3 I had already built it and published it. Over 200 church members now use the app I created. The course ROI is incredible."}],"faqs":[{"q":"Do I need programming experience?","a":"No! We teach Kotlin from absolute scratch. If you completed our Computer Literacy course, you have everything needed to start this course."},{"q":"What kind of computer do I need?","a":"Android Studio requires at least 8GB RAM (16GB recommended) and 4GB free disk space. Windows, Mac, and Linux all work. We provide an optimization guide for slower computers."},{"q":"Can I publish apps to earn money?","a":"Yes! Google Play allows you to sell apps, use in-app purchases, and run ads. Many graduates earn income through their apps. We cover monetization strategies in the final module."},{"q":"What comes after this course?","a":"We recommend our Advanced Android course covering Firebase, Jetpack Compose, and enterprise Android patterns. Or explore our Cross-Platform development course with Flutter."}]};
COURSES_DB['marketing'] = {"id":"marketing","title":"Digital Marketing Professional Certificate","shortDesc":"For business owners, marketers, and freelancers, master SEO, Facebook and Google advertising, email marketing, and analytics to grow any Liberian or African business online and measure real results.","category":"Digital Marketing","icon":"📢","gradient":"linear-gradient(135deg,#b45309,#f59e0b)","instructor":"Grace Johnson","instructorTitle":"Digital Marketing Director & Growth Strategist","instructorBio":"Grace Johnson has led digital marketing for brands in Liberia, Ghana, and Nigeria for over 12 years. She has generated over $5M in client revenue through digital campaigns and trained over 2,100 marketers at TIH Academy.","rating":4.9,"reviewCount":890,"students":"2,100+","duration":"34h","level":"Intermediate","price":"FREE","origPrice":"$180","isFree":true,"badge":"free","certId":"TIH-2026-DM-0095","learn":["Develop a comprehensive digital marketing strategy for any business","Grow organic reach through Search Engine Optimization (SEO)","Build and manage professional social media presence on all major platforms","Run profitable paid advertising on Facebook, Instagram, and Google","Create compelling content that attracts and converts audiences","Use Google Analytics to measure and optimize marketing performance","Build and grow an email marketing list with high open rates","Execute an end-to-end digital marketing campaign with real results"],"requirements":["Basic computer and internet skills","A business, brand, or personal project to apply marketing skills to (recommended)","No prior marketing experience needed, this course starts with fundamentals"],"about":["Digital marketing is the most accessible path to growing a business in Africa today. With over 500 million internet users across the continent, digital channels offer unprecedented reach at a fraction of traditional advertising costs, if you know how to use them.","This course covers the complete digital marketing ecosystem: from SEO and content marketing that drives free organic traffic, to paid social media ads that can target any audience, to email marketing and analytics. You will build real campaigns, not just learn theory.","Whether you run a business, work in marketing, or want to start a freelance digital marketing career, this course gives you skills that are immediately applicable and commercially valuable. Our graduates manage marketing for top Liberian businesses and international brands."],"modules":[{"title":"Module 1: Digital Marketing Strategy & Content","icon":"📢","meta":"4 lessons · 40 min","lessons":[{"t":"1.1 Digital Marketing Fundamentals & the Customer Journey","d":"10:00","v":"iRjXccj4yRo"},{"t":"1.2 Content Marketing: Creating Content That Converts","d":"11:00","v":"gqRdIEIlzNs"},{"t":"1.3 Social Media Strategy: Platform Selection & Brand Voice","d":"10:30","v":"8LX60gToxrM"},{"t":"📝 Quiz: Digital Marketing Strategy","d":"10 questions","isQuiz":true,"quizId":"mod1"}]},{"title":"Module 2: SEO & Organic Growth","icon":"🔍","meta":"4 lessons · 42 min","lessons":[{"t":"2.1 SEO Foundations: How Google Ranks Websites","d":"10:30","v":"WR_5_gJVA2c"},{"t":"2.2 Keyword Research & On-Page SEO","d":"11:30","v":"VPDe8XL7Mh8"},{"t":"2.3 Link Building & Technical SEO Essentials","d":"10:30","v":"C5ddo63kHHI"},{"t":"📝 Quiz: SEO & Organic Marketing","d":"10 questions","isQuiz":true,"quizId":"mod2"}]},{"title":"Module 3: Paid Advertising & Email Marketing","icon":"💰","meta":"4 lessons · 46 min","lessons":[{"t":"3.1 Facebook & Instagram Ads: Audience Targeting & Campaigns","d":"13:00","v":"-CsBl3tv-X0"},{"t":"3.2 Google Ads: Search, Display & Performance Max","d":"12:00","v":"u0r3y1q0fLQ"},{"t":"3.3 Email Marketing: List Building, Automation & Sequences","d":"11:30","v":"2fBxrhV3Nk0"},{"t":"🛠️ Project: Full Digital Marketing Campaign","d":"Project","isProject":true}]},{"title":"Module 4: Analytics, Optimization & Career","icon":"🏆","meta":"4 lessons · 38 min","lessons":[{"t":"4.1 Google Analytics 4: Measuring What Matters","d":"11:00","v":"mKu6FI53BxE"},{"t":"4.2 A/B Testing & Conversion Rate Optimization","d":"9:30","v":"xGpwhYiDCSg"},{"t":"4.3 Digital Marketing Career & Freelancing in Africa","d":"9:00","v":"1pejHrRIzAY"},{"t":"📝 Quiz: Analytics, Optimization & Career","d":"10 questions","isQuiz":true,"quizId":"mod4"}]},{"title":"Module 5: Mobile-First & WhatsApp Marketing for African Audiences","icon":"📱","meta":"4 lessons · reading + quiz","lessons":[{"t":"5.1 WhatsApp Business Marketing: Catalogs, Broadcasts & Customer Care","d":"Video + notes","v":"mGJyCH5BIi8"},{"t":"5.2 Social Commerce & Mobile Money: Selling Where Your Customers Already Are","d":"Video + notes","v":"K6AEFYA5QuM"},{"t":"5.3 Influencer, Community & Offline-to-Online Marketing","d":"Video + notes","v":"yLNSQyExhTU"},{"t":"📝 Quiz: Mobile-First & WhatsApp Marketing","d":"10 questions","isQuiz":true,"quizId":"mod5"}]},{"title":"Module 6: Capstone, Launching Your Digital Marketing Career & Agency","icon":"🚀","meta":"4 lessons · capstone + final","lessons":[{"t":"6.1 Building a Results-Driven Portfolio & Case Studies","d":"Video + notes","v":"gxz13n0CGzo"},{"t":"6.2 Winning Clients: Pitching, Pricing & Freelance Business Setup","d":"Video + notes","v":"RwqyuFnFzII"},{"t":"6.3 Capstone Project: Running a Full Campaign End-to-End & Reporting Like a Pro","d":"Video + notes","v":"lviXtSN-iUw"},{"t":"🏆 Final Assessment & Certificate","d":"20 questions","isQuiz":true,"quizId":"final","isFinal":true}]}],"reviews":[{"name":"Fatima Kamara","loc":"Monrovia, Liberia","date":"May 2026","bg":"#002868","init":"FK","rating":5,"text":"Grace Johnson is a phenomenal instructor. I landed a remote digital marketing job within 2 months of completing this course. The Facebook Ads module alone was worth 10 times the course price, I immediately ran profitable campaigns."},{"name":"Joseph Blamo","loc":"Buchanan, Liberia","date":"April 2026","bg":"#E31E24","init":"JB","rating":5,"text":"I use everything from this course every single day in my business. Organic reach is up 400% and my paid ads now have positive ROAS. Grace teaches with real results and real numbers. Absolutely life-changing course."},{"name":"Mary Kolie","loc":"Gbarnga, Liberia","date":"March 2026","bg":"#10b981","init":"MK","rating":5,"text":"The SEO module transformed my blog from zero to 1,000 monthly organic visitors in 3 months. The email marketing section gave me tools to build a subscriber list that is now my most valuable business asset."},{"name":"Thomas Sirleaf","loc":"Harper, Maryland County","date":"June 2026","bg":"#7c3aed","init":"TS","rating":4,"text":"Comprehensive coverage of every important digital marketing channel. The campaign project in Module 3 was excellent practical experience. I now manage marketing for two businesses in addition to my own, the skills are immediately monetizable."}],"faqs":[{"q":"Do I need a business to take this course?","a":"No, but having a project to apply your learning to (a business, nonprofit, personal brand, or side project) will dramatically accelerate your results."},{"q":"How much do Facebook and Google Ads cost?","a":"You can start with as little as $5/day. This course teaches you to make every dollar count with proper targeting and testing so you don't waste budget."},{"q":"Will this help me get a marketing job?","a":"Yes. Digital marketing is one of the fastest-growing career fields in Africa. Our certificate plus your campaign portfolio from this course makes you highly competitive for marketing roles."},{"q":"Is this course updated for current platforms?","a":"Yes. Digital marketing changes rapidly and TIH updates this course quarterly. Enrolled students get all updates free, including new modules on emerging platforms and AI in marketing."}]};
COURSES_DB['cybersecurity'] = {"id":"cybersecurity","title":"Cybersecurity Fundamentals & Ethical Hacking","shortDesc":"For IT and security-minded learners, understand how cyber attacks work, test systems ethically with Kali Linux, and prepare for CompTIA Security+ and CEH exams.","category":"Cybersecurity","icon":"🔒","gradient":"linear-gradient(135deg,#7f1d1d,#e31e24)","instructor":"Emmanuel Duo","instructorTitle":"Certified Ethical Hacker & Cybersecurity Consultant","instructorBio":"Emmanuel Duo holds a CEH (Certified Ethical Hacker) and CISSP certification with 10 years in cybersecurity consulting for banks, government agencies, and NGOs across West Africa. He has secured over 50 organizations from cyber threats.","rating":4.8,"reviewCount":389,"students":"1,100+","duration":"36h","level":"Intermediate","price":"FREE","origPrice":"$200","isFree":true,"badge":"free","certId":"TIH-2026-CS-0038","learn":["Understand the cybersecurity landscape and common threat types","Set up and use Kali Linux for security testing","Perform network scanning and vulnerability assessment","Understand and demonstrate common attack techniques ethically","Implement firewalls, VPNs, and network security controls","Conduct web application security testing","Apply security incident response procedures","Prepare for industry certifications: CompTIA Security+ and CEH"],"requirements":["Basic networking knowledge (IP addresses, DNS, HTTP) is helpful but not required","Computer with at least 8GB RAM to run virtual machines","Strong ethical commitment, this course is for defensive and educational purposes only"],"about":["Cybercrime costs African businesses over $3.5 billion annually, and the demand for cybersecurity professionals far exceeds supply across the continent. This course prepares you to fill that gap with practical, hands-on security skills.","Using a learn-by-doing approach with real tools (Kali Linux, Nmap, Wireshark, Metasploit), you will understand how attacks work so you can prevent and detect them. Every technique is taught in controlled environments for ethical, defensive purposes.","This course is designed for IT professionals seeking security specialization, system administrators, developers wanting to build secure software, and anyone seriously considering a cybersecurity career. Our graduates work for banks, telcos, and government agencies across West Africa."],"modules":[{"title":"Module 1: Cybersecurity Fundamentals","icon":"🔒","meta":"4 lessons · 42 min","lessons":[{"t":"1.1 Cybersecurity Landscape: Threats, Actors & Attack Vectors","d":"11:00","v":"4lwiQ5hXwCo"},{"t":"1.2 Networking Fundamentals for Security: TCP/IP, DNS & Ports","d":"12:00","v":"ltBWJIhcjpA"},{"t":"1.3 Cryptography, Passwords & Authentication Security","d":"11:00","v":"kb_scuDUHls"},{"t":"📝 Quiz: Cybersecurity Fundamentals","d":"10 questions","isQuiz":true,"quizId":"mod1"}]},{"title":"Module 2: Network & System Security","icon":"🛡️","meta":"4 lessons · 46 min","lessons":[{"t":"2.1 Setting Up Kali Linux & Security Lab Environment","d":"12:00","v":"wX75Z-4MEoM"},{"t":"2.2 Network Scanning & Reconnaissance with Nmap","d":"12:00","v":"HPDgPg4aWqs"},{"t":"2.3 Firewalls, IDS/IPS & Network Defense Strategies","d":"12:30","v":"AwEZP2KQPJ8"},{"t":"📝 Quiz: Network Security","d":"10 questions","isQuiz":true,"quizId":"mod2"}]},{"title":"Module 3: Ethical Hacking & Penetration Testing","icon":"⚔️","meta":"4 lessons · 48 min","lessons":[{"t":"3.1 Ethical Hacking Methodology & Legal Framework","d":"11:00","v":"9DrnMjs5UVA"},{"t":"3.2 Vulnerability Assessment & Exploitation Basics","d":"13:00","v":"x43N_p0QGXU"},{"t":"3.3 Web Application Security: OWASP Top 10","d":"13:00","v":"Jzr0Jdnq_EI"},{"t":"🛠️ Project: Penetration Test Report on a Lab Environment","d":"Project","isProject":true}]},{"title":"Module 4: Incident Response & Career","icon":"🏆","meta":"4 lessons · 40 min","lessons":[{"t":"4.1 Security Incident Response & Digital Forensics Basics","d":"11:00","v":"Is2RcF0FJL4"},{"t":"4.2 Security Compliance: GDPR, ISO 27001 & African Data Laws","d":"10:00","v":"V7qVZD1z9pA"},{"t":"4.3 Cybersecurity Certifications & Career Pathways (CEH, Security+)","d":"9:30","v":"pOfCmL1YRIQ"},{"t":"📝 Quiz: Incident Response & Career","d":"10 questions","isQuiz":true,"quizId":"mod4"}]},{"title":"Module 5: Cloud, Mobile & Data Security in Practice","icon":"☁️","meta":"4 lessons · reading + quiz","lessons":[{"t":"5.1 Cloud Security Fundamentals & the Shared Responsibility Model","d":"Video + notes","v":"Qt9lhzFhW_c"},{"t":"5.2 Mobile & Mobile Money Security","d":"Video + notes","v":"4PJPWC8qWG0"},{"t":"5.3 Data Protection, Backups & Business Continuity","d":"Video + notes","v":"cEb79PGWCL8"},{"t":"📝 Quiz: Cloud, Mobile & Data Security","d":"10 questions","isQuiz":true,"quizId":"mod5"}]},{"title":"Module 6: Capstone, Building a Professional Security Practice & Career","icon":"🎯","meta":"4 lessons · capstone + final","lessons":[{"t":"6.1 Security Frameworks, Risk Management & Threat Modeling","d":"Video + notes","v":"rEnJYNkUde0"},{"t":"6.2 Building Your Home Lab, Certifications & Cybersecurity Career","d":"Video + notes","v":"v7BNtpw53AA"},{"t":"6.3 Capstone Project: End-to-End Security Assessment & Professional Report","d":"Video + notes","v":"3Kq1MIfTWCE"},{"t":"🏆 Final Assessment & Certificate","d":"20 questions","isQuiz":true,"quizId":"final","isFinal":true}]}],"reviews":[{"name":"Fatima Kamara","loc":"Monrovia, Liberia","date":"May 2026","bg":"#002868","init":"FK","rating":5,"text":"Emmanuel Duo is a world-class instructor. The hands-on lab environment made learning to hack (ethically!) completely safe and practical. I passed my CompTIA Security+ exam 2 weeks after finishing this course."},{"name":"Joseph Blamo","loc":"Buchanan, Liberia","date":"April 2026","bg":"#E31E24","init":"JB","rating":5,"text":"This course opened my eyes to how vulnerable most systems are. I immediately applied the knowledge to harden my company's network. The OWASP module was particularly revelatory. Excellent investment for any IT professional."},{"name":"Mary Kolie","loc":"Gbarnga, Liberia","date":"March 2026","bg":"#10b981","init":"MK","rating":4,"text":"Comprehensive and well-structured. The penetration testing project was challenging and rewarding. I now consult for small businesses on cybersecurity. The certificate carries real weight with Liberian organizations taking security seriously."},{"name":"Thomas Sirleaf","loc":"Harper, Maryland County","date":"June 2026","bg":"#7c3aed","init":"TS","rating":5,"text":"Best cybersecurity training available in West Africa. Emmanuel teaches with real-world examples that make concepts stick. The course prepared me thoroughly for my CEH certification. Highly recommended for anyone in IT."}],"faqs":[{"q":"Is this course legal and ethical?","a":"Yes. All techniques are taught in controlled lab environments for defensive and educational purposes. We emphasize ethics and legal compliance throughout, and require students to agree to an ethical use pledge."},{"q":"What certifications can this help me prepare for?","a":"This course prepares you for CompTIA Security+, CEH (Certified Ethical Hacker), and provides a foundation for CISSP. We recommend these certifications to complement your TIH certificate."},{"q":"Do I need cybersecurity experience?","a":"Basic networking knowledge is helpful but not required. We provide a networking primer in Module 1. IT professionals and developers will advance faster, but beginners can succeed with dedication."},{"q":"What careers does cybersecurity lead to?","a":"Security Analyst, Penetration Tester, SOC Analyst, Security Engineer, and CISO are all in high demand across Africa. Average salaries are significantly above general IT roles."}]};
COURSES_DB['entrepreneurship'] = {"id":"entrepreneurship","title":"Entrepreneurship & Startup Launch Program","shortDesc":"For first-time and experienced entrepreneurs, validate your idea, write a fundable business plan, access grants and investors, and register and launch your business in Liberia.","category":"Entrepreneurship","icon":"💡","gradient":"linear-gradient(135deg,#92400e,#f59e0b)","instructor":"Thomas Bility","instructorTitle":"Serial Entrepreneur & Startup Mentor","instructorBio":"Thomas Bility has founded 4 businesses in Liberia and trained entrepreneurs across West Africa for over 15 years. He has helped secure over $2M in funding for Liberian startups and is a regular advisor at startup competitions regionally.","rating":4.8,"reviewCount":598,"students":"2,400+","duration":"30h","level":"All Levels","price":"FREE","origPrice":"$150","isFree":true,"badge":"free","certId":"TIH-2026-EP-0083","learn":["Validate business ideas quickly and cheaply before investing resources","Develop a comprehensive business plan and model canvas","Conduct market research and competitive analysis in the African market","Build financial projections and understand startup financial statements","Identify and access funding sources: grants, loans, investors, and bootstrapping","Register your business and understand legal structures in Liberia","Build and pitch your business to investors and partners","Implement growth strategies to scale your business sustainably"],"requirements":["No prior business experience needed, we guide you from the very beginning","A business idea (or willingness to develop one during the course)","Commitment to completing the business plan project in each module"],"about":["Liberia and West Africa are full of entrepreneurial opportunity, but most business ideas never become businesses because founders lack the knowledge and tools to take them from idea to execution. This course bridges that gap.","Drawing on real Liberian and African business case studies, this course takes you through every stage of the startup journey: idea validation, business modeling, legal setup, financial planning, fundraising, marketing, and scaling. No theory without action.","By the end of this program, you will have a complete, fundable business plan and the confidence to launch and grow your business. Thousands of graduates have used this course to start businesses that now employ people and contribute to Liberia's economy."],"modules":[{"title":"Module 1: Idea to Business Opportunity","icon":"💡","meta":"4 lessons · 38 min","lessons":[{"t":"1.1 Entrepreneurial Mindset & Opportunity Recognition","d":"9:00","v":"4hshq-o0vSI"},{"t":"1.2 Idea Validation: Testing Before You Invest","d":"10:30","v":"Th8JoIan4dg"},{"t":"1.3 Market Research & the African Consumer","d":"10:00","v":"KCEWgq8S9gM"},{"t":"📝 Quiz: Entrepreneurship Foundations","d":"10 questions","isQuiz":true,"quizId":"mod1"}]},{"title":"Module 2: Business Planning & Legal Setup","icon":"📋","meta":"4 lessons · 42 min","lessons":[{"t":"2.1 Business Model Canvas & Value Proposition","d":"11:00","v":"ReM1uqmVfP0"},{"t":"2.2 Writing a Compelling Business Plan","d":"12:00","v":"XK9XYa5-MCw"},{"t":"2.3 Legal Structures & Business Registration in Liberia","d":"11:00","v":"fj6zbwAXpzE"},{"t":"📝 Quiz: Business Planning & Models","d":"10 questions","isQuiz":true,"quizId":"mod2"}]},{"title":"Module 3: Funding & Financial Management","icon":"💰","meta":"4 lessons · 44 min","lessons":[{"t":"3.1 Startup Funding Options: Grants, Loans, Angels & VC","d":"11:30","v":"Cw58F0k8BDg"},{"t":"3.2 Financial Projections, Cash Flow & Break-Even Analysis","d":"12:00","v":"7Ljc6NoNg6M"},{"t":"3.3 Grant Writing & Investor Pitch Preparation","d":"11:30","v":"Tk-RdCFSrKU"},{"t":"🛠️ Project: Complete Business Plan & Pitch Deck","d":"Project","isProject":true}]},{"title":"Module 4: Launch, Growth & Scale","icon":"🏆","meta":"4 lessons · 38 min","lessons":[{"t":"4.1 Go-to-Market Strategy & First Customers","d":"10:00","v":"UWqzT95Lkno"},{"t":"4.2 Growth Hacking & Scaling Strategies for African Markets","d":"10:00","v":"8_6uU6KgexE"},{"t":"4.3 Building a Team & Leadership for Entrepreneurs","d":"9:00","v":"HL80lXafRL0"},{"t":"📝 Quiz: Launch, Growth & Scale","d":"10 questions","isQuiz":true,"quizId":"mod4"}]},{"title":"Module 5: Sales, Operations & Managing a Growing Business","icon":"⚙️","meta":"4 lessons · reading + quiz","lessons":[{"t":"5.1 Sales Skills & Building a Repeatable Sales Process","d":"Video + notes","v":"hZI83oKyDq0"},{"t":"5.2 Operations, Systems & Delivering Consistent Quality","d":"Video + notes","v":"hFJQjlMEcqk"},{"t":"5.3 Financial Management, Pricing & Managing People","d":"Video + notes","v":"Wzwpou8d7v4"},{"t":"📝 Quiz: Sales, Operations & Management","d":"10 questions","isQuiz":true,"quizId":"mod5"}]},{"title":"Module 6: Capstone, Scaling to a Sustainable Enterprise","icon":"🌱","meta":"4 lessons · capstone + final","lessons":[{"t":"6.1 Growth Strategy, Partnerships & Regional Expansion","d":"Video + notes","v":"4OO3MXzqNII"},{"t":"6.2 Building Resilience, Culture & Good Governance","d":"Video + notes","v":"9B-gyOi8CZs"},{"t":"6.3 Capstone Project: Your Enterprise Growth Plan & Investor-Ready Pitch","d":"Video + notes","v":"71TriLlszpU"},{"t":"🏆 Final Assessment & Certificate","d":"20 questions","isQuiz":true,"quizId":"final","isFinal":true}]}],"reviews":[{"name":"Fatima Kamara","loc":"Monrovia, Liberia","date":"May 2026","bg":"#002868","init":"FK","rating":5,"text":"Thomas Bility brings real Liberian business experience to every lesson. After this course I registered my business, secured a $15,000 grant, and now employ 8 people. The business plan project was the foundation for everything."},{"name":"Joseph Blamo","loc":"Buchanan, Liberia","date":"April 2026","bg":"#E31E24","init":"JB","rating":5,"text":"I had been sitting on my business idea for 3 years. This course gave me the tools, confidence, and roadmap to finally launch. Six months later my business is profitable. The funding module opened doors I didn't know existed."},{"name":"Mary Kolie","loc":"Gbarnga, Liberia","date":"March 2026","bg":"#10b981","init":"MK","rating":5,"text":"The most practical entrepreneurship training I have ever seen. Thomas doesn't teach from textbooks, he teaches from real Liberian business experience. The pitch deck project prepared me perfectly for investor meetings."},{"name":"Thomas Sirleaf","loc":"Harper, Maryland County","date":"June 2026","bg":"#7c3aed","init":"TS","rating":4,"text":"Excellent course structure. The MVP validation approach saved me from investing in a business idea that wouldn't have worked. The market research tools are invaluable for anyone starting a business in rural Liberia."}],"faqs":[{"q":"Do I need money to start a business before taking this course?","a":"No. One of the core lessons is how to validate and start a business with minimal capital. Many successful Liberian businesses started with under $500."},{"q":"Will this help me access grants?","a":"Yes. The grant writing module specifically covers major grants available to Liberian entrepreneurs including USAID, World Bank, and Tony Elumelu Foundation programs."},{"q":"Is this course for people with no business experience?","a":"This course is designed for everyone from first-time entrepreneurs to experienced business owners wanting to scale. The content is structured to benefit all levels."},{"q":"How practical is this course?","a":"Every module includes a hands-on project. By course end you will have a complete business plan, financial projections, pitch deck, and go-to-market strategy, ready for execution."}]};
COURSES_DB['project-mgmt'] = {"id":"project-mgmt","title":"Project Management Professional Certificate","shortDesc":"For professionals in any sector, learn PMBOK and Agile frameworks, build Gantt charts and risk registers, lead project teams, and prepare for the globally recognized PMP certification examination.","category":"Project Management","icon":"📋","gradient":"linear-gradient(135deg,#064e3b,#047857)","instructor":"Dr. Mary Weah","instructorTitle":"Certified PMP & Organizational Strategy Consultant","instructorBio":"Dr. Mary Weah holds PMP and PRINCE2 certifications with 18 years managing large-scale projects for UN agencies, World Bank programs, and Liberian government ministries. She is TIH's Business & Management curriculum lead.","rating":4.9,"reviewCount":478,"students":"3,200+","duration":"32h","level":"All Levels","price":"FREE","origPrice":"$200","isFree":true,"badge":"free","certId":"TIH-2026-PM-0127","learn":["Understand the 5 project management process groups and 10 knowledge areas","Create project charters, scope statements, and work breakdown structures","Build project schedules using Gantt charts and critical path method","Develop and manage project budgets and cost controls","Identify, assess, and manage project risks proactively","Lead project teams and manage stakeholder communication","Apply Agile and Scrum frameworks for flexible project delivery","Prepare effectively for the PMP certification examination"],"requirements":["No prior project management experience needed","Basic computer and email communication skills","Professional work experience (any field) is helpful but not required"],"about":["Every organization, businesses, NGOs, government agencies, and international development organizations, needs people who can successfully manage projects. Project management is one of the most transferable and universally valued professional skills.","This course combines the traditional PMBOK framework used in PMP certification preparation with Agile/Scrum methodologies increasingly demanded by modern organizations. Both are taught with real African project examples: infrastructure, health programs, NGO initiatives, and business projects.","Graduates have passed PMP exams, secured project manager roles at major organizations including UN agencies and World Bank-funded programs, and successfully delivered multimillion-dollar projects in Liberia and across Africa."],"modules":[{"title":"Module 1: PM Fundamentals & Project Initiation","icon":"📋","meta":"4 lessons · 40 min","lessons":[{"t":"1.1 What is Project Management? Processes & Knowledge Areas","d":"10:30","v":"iopMMoHstJM"},{"t":"1.2 Project Charter & Stakeholder Identification","d":"10:30","v":"SPj-Luod9tI"},{"t":"1.3 Scope Management: WBS & Requirements","d":"11:00","v":"PyR2VLP3xnA"},{"t":"📝 Quiz: PM Fundamentals & Initiation","d":"10 questions","isQuiz":true,"quizId":"mod1"}]},{"title":"Module 2: Planning, Schedule, Budget & Risk","icon":"📅","meta":"4 lessons · 46 min","lessons":[{"t":"2.1 Project Scheduling: Gantt Charts & Critical Path Method","d":"12:00","v":"YDxAKKVdMVM"},{"t":"2.2 Budget Estimation & Cost Management","d":"11:30","v":"EyPFi0YO32M"},{"t":"2.3 Risk Management: Identification, Assessment & Response","d":"12:00","v":"r1szmmkUPH8"},{"t":"📝 Quiz: Project Planning","d":"10 questions","isQuiz":true,"quizId":"mod2"}]},{"title":"Module 3: Execution, Monitoring & Agile","icon":"⚡","meta":"4 lessons · 44 min","lessons":[{"t":"3.1 Project Execution: Leading Teams & Managing Quality","d":"11:00","v":"1rQT1R3S2BQ"},{"t":"3.2 Monitoring & Controlling: EVM, KPIs & Status Reporting","d":"12:00","v":"boIRGwGJ-Ds"},{"t":"3.3 Agile & Scrum: Sprints, Backlogs & Stand-ups","d":"12:00","v":"KmEMtUzMlIk"},{"t":"🛠️ Project: Full Project Plan for a Real Initiative","d":"Project","isProject":true}]},{"title":"Module 4: Closure, Communication & PMP Prep","icon":"🏆","meta":"4 lessons · 38 min","lessons":[{"t":"4.1 Project Closure & Lessons Learned","d":"9:30","v":"gSOdc2Y5tTk"},{"t":"4.2 Stakeholder Communication & Change Management","d":"10:00","v":"bV9yUQV6D60"},{"t":"4.3 PMP Exam Preparation & Professional Development","d":"10:00","v":"vzqDTSZOTic"},{"t":"📝 Quiz: Closure, Communication & PMP Prep","d":"10 questions","isQuiz":true,"quizId":"mod4"}]},{"title":"Module 5: PM Tools & Managing Donor-Funded Projects","icon":"🛠️","meta":"4 lessons · reading + quiz","lessons":[{"t":"5.1 Project Management Software: Trello, Asana & MS Project","d":"Video + notes","v":"C5b_4aFeF2E"},{"t":"5.2 Donor-Funded Projects: Logframes, Work Plans & Compliance","d":"Video + notes","v":"00Rbll3ZNk0"},{"t":"5.3 Procurement, Contracts & Financial Stewardship","d":"Video + notes","v":"ktSzxVEnTZ8"},{"t":"📝 Quiz: PM Tools & Donor-Funded Projects","d":"10 questions","isQuiz":true,"quizId":"mod5"}]},{"title":"Module 6: Capstone, Your Project Management Career","icon":"🚀","meta":"4 lessons · capstone + final","lessons":[{"t":"6.1 Building Your PM Portfolio & Case Studies","d":"Video + notes","v":"521iU9T4TBg"},{"t":"6.2 From Projects to Programs: PMOs & Program Management","d":"Video + notes","v":"fAC7up3jc3k"},{"t":"6.3 Your PM Career: Jobs, Interviews & Certification Roadmap","d":"Video + notes","v":"UQ71PhWRDEQ"},{"t":"🏆 Final Assessment & Certificate","d":"20 questions","isQuiz":true,"quizId":"final","isFinal":true}]}],"reviews":[{"name":"Fatima Kamara","loc":"Monrovia, Liberia","date":"May 2026","bg":"#002868","init":"FK","rating":5,"text":"Dr. Weah is the best PM instructor I have ever encountered. After this course I passed my PMP exam on the first attempt. I now manage a $3M World Bank project in Liberia. This course was the foundation for my entire career change."},{"name":"Joseph Blamo","loc":"Buchanan, Liberia","date":"April 2026","bg":"#E31E24","init":"JB","rating":5,"text":"The combination of PMBOK and Agile in one course is brilliant. The Scrum module prepared me for my tech company role perfectly. Dr. Weah uses real African project examples which make everything immediately relevant and applicable."},{"name":"Mary Kolie","loc":"Gbarnga, Liberia","date":"March 2026","bg":"#10b981","init":"MK","rating":5,"text":"I manage health projects for an international NGO and this course transformed my approach completely. The risk management and EVM modules are outstanding. My project delivery rates improved dramatically after applying these tools."},{"name":"Thomas Sirleaf","loc":"Harper, Maryland County","date":"June 2026","bg":"#7c3aed","init":"TS","rating":4,"text":"Excellent comprehensive course. The full project plan assignment pushed me to apply every concept from the course in one integrated deliverable. I showed the plan in a job interview and was hired immediately. Highly recommended."}],"faqs":[{"q":"Will this prepare me for the PMP certification?","a":"Yes! This course aligns with PMBOK Guide 7th edition and covers all major PMP exam domains. We recommend additional practice exams after completing the course."},{"q":"Do I need project management experience?","a":"No prior PM experience is required. The course builds your knowledge from the ground up. Having any work experience (in any field) provides helpful context."},{"q":"What industries use project management?","a":"Every industry: construction, healthcare, NGOs, government, banking, technology, agriculture, and more. Every organization that runs projects needs project managers."},{"q":"How does this course cover Agile and Scrum?","a":"Module 3 covers Agile fundamentals and Scrum in depth, including sprints, backlogs, retrospectives, and roles. This prepares you for both traditional PM and modern agile environments."}]};
COURSES_DB['office'] = {"id":"office","title":"Microsoft Office Mastery: Word, Excel & PowerPoint","shortDesc":"For job seekers and professionals, go beyond basics to master advanced Word, Excel, and PowerPoint features like mail merge, pivot tables, and slide masters.","category":"Computer Fundamentals","icon":"💼","gradient":"linear-gradient(135deg,#d97706,#f59e0b)","instructor":"Samuel Doe","instructorTitle":"Microsoft Certified Trainer & Productivity Expert","instructorBio":"Samuel Doe is a Microsoft Certified Trainer (MCT) with 15 years teaching Office productivity to businesses, government agencies, and NGOs across Liberia. He has helped over 5,000 professionals master the Microsoft Office suite.","rating":4.8,"reviewCount":943,"students":"4,800+","duration":"28h","level":"Beginner","price":"FREE","origPrice":"$120","isFree":true,"badge":"free","certId":"TIH-2026-MO-0156","learn":["Create professional documents, reports, and CVs in Microsoft Word","Use advanced Word features: styles, tables of contents, mail merge","Build spreadsheets with essential Excel formulas and functions","Create pivot tables and charts to analyze and visualize data","Design compelling presentations in Microsoft PowerPoint","Use PowerPoint animations, slide masters, and presentation techniques","Collaborate using Microsoft 365 OneDrive, Teams, and SharePoint","Improve productivity with keyboard shortcuts and workflow automation"],"requirements":["Basic computer skills, ability to use a keyboard and mouse","Microsoft Office 2016 or later (or Microsoft 365 subscription)","No prior Office experience needed, this course covers all three applications completely"],"about":["Microsoft Office is the most widely used productivity software suite in the world. In Liberia and across Africa, proficiency in Word, Excel, and PowerPoint is required for virtually every office job. This course builds that proficiency comprehensively.","Going beyond basic skills, this course teaches advanced features that separate proficient users from true Office masters, mail merge, pivot tables, data analysis, slide masters, and Microsoft 365 collaboration tools that are increasingly standard in modern workplaces.","Whether you are preparing for a job interview, looking to perform better at work, or wanting to start freelancing as an Office trainer or virtual assistant, this course gives you everything you need. Our graduates consistently report immediate career advancement from these skills."],"modules":[{"title":"Module 1: Microsoft Word, Professional Documents","icon":"📄","meta":"4 lessons · 42 min","lessons":[{"t":"1.1 Word Interface, Formatting & Document Structure","d":"10:30","v":"EuWTrvT_YyY"},{"t":"1.2 Professional CVs, Letters & Reports with Styles","d":"12:00","v":"3eIlHtHDGDs"},{"t":"1.3 Tables, Images, Mail Merge & Advanced Features","d":"12:00","v":"rGG-In7PAEk"},{"t":"📝 Quiz: Microsoft Word","d":"10 questions","isQuiz":true,"quizId":"mod1"}]},{"title":"Module 2: Microsoft Excel, Data & Analysis","icon":"📊","meta":"4 lessons · 46 min","lessons":[{"t":"2.1 Excel Essentials: Formulas, Functions & Formatting","d":"12:00","v":"7_vMFvnGTlc"},{"t":"2.2 VLOOKUP, IF Statements & Essential Data Functions","d":"12:30","v":"bsuP2dD3rec"},{"t":"2.3 Pivot Tables, Charts & Dashboard Creation","d":"13:00","v":"9NUjHBNWe9M"},{"t":"📝 Quiz: Microsoft Excel","d":"10 questions","isQuiz":true,"quizId":"mod2"}]},{"title":"Module 3: Microsoft PowerPoint, Presentations","icon":"🎞️","meta":"4 lessons · 40 min","lessons":[{"t":"3.1 PowerPoint Fundamentals: Layouts, Themes & Master Slides","d":"10:00","v":"QiVSIvB1xis"},{"t":"3.2 Advanced Animations, Transitions & Multimedia","d":"11:00","v":"cwPaqUC1jT4"},{"t":"3.3 Data Visualization & Charts in PowerPoint","d":"10:00","v":"ycyySK5bdRg"},{"t":"🛠️ Project: Professional Business Presentation","d":"Project","isProject":true}]},{"title":"Module 4: Microsoft 365 & Productivity Mastery","icon":"🏆","meta":"4 lessons · 36 min","lessons":[{"t":"4.1 Microsoft 365: OneDrive, Teams & SharePoint Collaboration","d":"10:00","v":"nbhZE_mza2g"},{"t":"4.2 Keyboard Shortcuts & Productivity Optimization","d":"9:00","v":"u0--Ye7bUP4"},{"t":"4.3 Microsoft Outlook: Professional Email & Calendar Management","d":"9:00","v":"TzNQkMTHKuM"},{"t":"📝 Quiz: Microsoft 365 & Productivity Mastery","d":"10 questions","isQuiz":true,"quizId":"mod4"}]},{"title":"Module 5: Advanced Excel, Power Functions, Clean Data & Automation","icon":"⚡","meta":"4 lessons · reading + quiz","lessons":[{"t":"5.1 XLOOKUP, INDEX-MATCH & Named Ranges","d":"Video + notes","v":"4wQ0KmttgcQ"},{"t":"5.2 Data Cleaning & Validation: Trustworthy Spreadsheets","d":"Video + notes","v":"oT4emh72fuA"},{"t":"5.3 Automation: Power Query & Macro Basics","d":"Video + notes","v":"DQPHzp2ezpw"},{"t":"📝 Quiz: Advanced Excel & Automation","d":"10 questions","isQuiz":true,"quizId":"mod5"}]},{"title":"Module 6: Capstone, Office Skills at Work & Beyond","icon":"🏆","meta":"4 lessons · capstone + final","lessons":[{"t":"6.1 Capstone Part 1: The Professional Report in Word","d":"Video + notes","v":"VFMPLeC7h0I"},{"t":"6.2 Capstone Part 2: Excel Dashboard & Executive Briefing in PowerPoint","d":"Video + notes","v":"S0i4CdKi1i4"},{"t":"6.3 Careers: MOS Certification, Virtual Assistant Work & Freelancing","d":"Video + notes","v":"Y5waTxDKZ3c"},{"t":"🏆 Final Assessment & Certificate","d":"20 questions","isQuiz":true,"quizId":"final","isFinal":true}]}],"reviews":[{"name":"Fatima Kamara","loc":"Monrovia, Liberia","date":"May 2026","bg":"#002868","init":"FK","rating":5,"text":"I knew the basics before this course but Samuel took me to a completely new level. The advanced Excel module specifically, pivot tables and VLOOKUP, got me promoted to a data reporting role. Excellent investment."},{"name":"Joseph Blamo","loc":"Buchanan, Liberia","date":"April 2026","bg":"#E31E24","init":"JB","rating":5,"text":"The mail merge module alone saved me 4 hours of work every month. The PowerPoint slide master section transformed my presentations from amateur to professional overnight. My clients now specifically comment on presentation quality."},{"name":"Mary Kolie","loc":"Gbarnga, Liberia","date":"March 2026","bg":"#10b981","init":"MK","rating":5,"text":"Most comprehensive Office training available in Liberia. I learned features in this course that I didn't know existed after 5 years using Office. The Microsoft 365 collaboration module is now essential knowledge in every workplace."},{"name":"Thomas Sirleaf","loc":"Harper, Maryland County","date":"June 2026","bg":"#7c3aed","init":"TS","rating":4,"text":"Very practical course. The keyboard shortcuts module doubled my productivity. I now teach these skills to junior staff at my organization. The certificate is a strong addition to any CV in the Liberian job market."}],"faqs":[{"q":"Do I need to buy Microsoft Office?","a":"Microsoft 365 Personal costs about $70/year and includes all apps plus 1TB OneDrive storage. A free 30-day trial covers the entire course. Many employers also provide Office licenses."},{"q":"Is this different from the Computer Literacy course?","a":"The Computer Literacy course covers Office at a basic introductory level. This course goes into advanced features of each application comprehensively, it's the deep-dive version."},{"q":"Will Office skills help me get a job?","a":"Almost every office job in Liberia requires Word, Excel, and PowerPoint proficiency. Listing Microsoft Office competency on your CV is table stakes for administrative, finance, and management roles."},{"q":"Does this cover Google Workspace too?","a":"This course focuses on Microsoft Office specifically. If you need Google Workspace skills, our Data Analytics course covers Google Sheets in detail."}]};
COURSES_DB['leadership'] = {"id":"leadership","title":"Business Leadership Masterclass","shortDesc":"For emerging and experienced leaders, develop emotional intelligence, build high-performing teams, lead change, and create a personal leadership plan that drives lasting impact.","category":"Leadership","icon":"🎯","gradient":"linear-gradient(135deg,#78350f,#b45309)","instructor":"Dr. Mary Weah","instructorTitle":"Business Strategy Consultant & Executive Coach","instructorBio":"Dr. Mary Weah holds an MBA and PhD in Organizational Leadership with 20 years advising C-suite executives, government ministers, and NGO directors across West Africa. She is TIH's highest-rated instructor and a leading voice on African leadership.","rating":4.9,"reviewCount":341,"students":"2,700+","duration":"28h","level":"All Levels","price":"FREE","origPrice":"$180","isFree":true,"badge":"free","certId":"TIH-2026-LD-0099","learn":["Understand your personal leadership style and how to develop it intentionally","Build high-performing teams and motivate people toward shared goals","Communicate with executive presence and influence stakeholders effectively","Lead through change and guide organizations through transformation","Apply strategic thinking and decision-making frameworks","Manage conflict, build consensus, and negotiate effectively","Develop emotional intelligence and self-awareness as a leader","Create a personal leadership development plan for continued growth"],"requirements":["No formal leadership experience required, this course develops leaders at all levels","An openness to honest self-assessment and personal growth","Some work experience (professional, community, or organizational) is helpful"],"about":["Leadership is the most critical capability gap in African organizations today. Technical skills get you hired, but leadership skills determine how far you go and how much impact you have. This masterclass develops both the strategic and human dimensions of exceptional leadership.","Drawing on globally proven leadership frameworks (situational leadership, emotional intelligence, transformational leadership) applied to African organizational contexts, this course is both rigorous and immediately practical. Every concept is applied to real leadership situations you face.","Whether you lead 2 people or 2,000, in business, government, civil society, or your community, this course will transform how you lead. Our graduates hold positions from team leader to CEO and consistently credit this course as a turning point in their leadership journey."],"modules":[{"title":"Module 1: Leadership Foundations & Self-Awareness","icon":"🎯","meta":"4 lessons · 38 min","lessons":[{"t":"1.1 What is Leadership? Styles, Theories & the African Context","d":"9:30","v":"tYW6X5qwnMw"},{"t":"1.2 Self-Assessment: Your Leadership Strengths & Gaps","d":"10:00","v":"Q-JClqIR5a4"},{"t":"1.3 Emotional Intelligence: The Foundation of Effective Leadership","d":"10:00","v":"kKbTi9_1lTg"},{"t":"📝 Quiz: Leadership Foundations","d":"10 questions","isQuiz":true,"quizId":"mod1"}]},{"title":"Module 2: Team Leadership & People Management","icon":"👥","meta":"4 lessons · 42 min","lessons":[{"t":"2.1 Building High-Performing Teams: Selection, Trust & Culture","d":"11:00","v":"L4UTybPoyn4"},{"t":"2.2 Motivation, Delegation & Accountability","d":"11:30","v":"SI6cOkDOoyE"},{"t":"2.3 Managing Conflict & Building Consensus","d":"11:00","v":"o0w1941xkjY"},{"t":"📝 Quiz: Team Leadership","d":"10 questions","isQuiz":true,"quizId":"mod2"}]},{"title":"Module 3: Strategic Leadership & Communication","icon":"📡","meta":"4 lessons · 44 min","lessons":[{"t":"3.1 Strategic Thinking & Decision-Making Frameworks","d":"11:30","v":"LerIITWNgvI"},{"t":"3.2 Executive Communication & Stakeholder Influence","d":"11:30","v":"0X1FiNxlHh0"},{"t":"3.3 Leading Change & Organizational Transformation","d":"12:00","v":"AAZgoKAqGE0"},{"t":"🛠️ Project: Personal Leadership Development Plan","d":"Project","isProject":true}]},{"title":"Module 4: Ethical Leadership, Cross-Cultural Leading & Developing Future Leaders","icon":"🏆","meta":"4 lessons · 36 min","lessons":[{"t":"4.1 Ethical Leadership & Corporate Governance","d":"9:30","v":"XjiRF_6cvcA"},{"t":"4.2 Leading Across Cultures & Generations","d":"9:00","v":"cyGuic7_ivo"},{"t":"4.3 Building Leadership Legacy & Developing Future Leaders","d":"9:00","v":"f8uw94S-yc4"},{"t":"📝 Quiz: Ethical Leadership & Leading Across Cultures","d":"10 questions","isQuiz":true,"quizId":"mod4"}]},{"title":"Module 5: Coaching, Feedback & Performance Leadership","icon":"🗣️","meta":"4 lessons · reading + quiz","lessons":[{"t":"5.1 Coaching Skills: The GROW Model & Powerful Questions","d":"Video + notes","v":"_TMM0lhukBg"},{"t":"5.2 Feedback That Builds People: The SBI Model & Feedback Culture","d":"Video + notes","v":"t3GjwVWapGo"},{"t":"5.3 Managing Performance & Difficult Conversations","d":"Video + notes","v":"GsRgHt4IIBU"},{"t":"📝 Quiz: Coaching, Feedback & Performance","d":"10 questions","isQuiz":true,"quizId":"mod5"}]},{"title":"Module 6: Capstone, Crisis Leadership & Your Leadership Brand","icon":"🧭","meta":"4 lessons · capstone + final","lessons":[{"t":"6.1 Leading Through Crisis & Uncertainty","d":"Video + notes","v":"eBXm0_8-rwU"},{"t":"6.2 Your Personal Leadership Brand & Executive Career","d":"Video + notes","v":"mBRHe1sRiZM"},{"t":"6.3 Capstone Project: Leading a Real Initiative & Measuring Your Impact","d":"Video + notes","v":"_zAiKx69kE0"},{"t":"🏆 Final Assessment & Certificate","d":"20 questions","isQuiz":true,"quizId":"final","isFinal":true}]}],"reviews":[{"name":"Fatima Kamara","loc":"Monrovia, Liberia","date":"May 2026","bg":"#002868","init":"FK","rating":5,"text":"Dr. Weah is simply magnificent. This course fundamentally changed how I lead my team. The emotional intelligence module showed me blind spots I never knew I had. My team's performance and morale have both improved dramatically."},{"name":"Joseph Blamo","loc":"Buchanan, Liberia","date":"April 2026","bg":"#E31E24","init":"JB","rating":5,"text":"I have taken leadership training from international consultants at 3 times the price of this course, nothing has been as practical and immediately applicable. The African context throughout makes this course uniquely relevant and valuable."},{"name":"Mary Kolie","loc":"Gbarnga, Liberia","date":"March 2026","bg":"#10b981","init":"MK","rating":5,"text":"The strategic thinking module gave me tools I use in every major decision. The personal leadership development plan was a transformative exercise. I now mentor 5 younger women in leadership because of the inspiration this course gave me."},{"name":"Thomas Sirleaf","loc":"Harper, Maryland County","date":"June 2026","bg":"#7c3aed","init":"TS","rating":5,"text":"One of the most valuable learning experiences of my career. Dr. Weah combines academic rigor with deep practical wisdom. I was promoted to Regional Director 4 months after completing this course. The timing was not a coincidence."}],"faqs":[{"q":"Is this course only for people who already lead teams?","a":"No. This course is valuable at every career stage. Many of the most impactful leadership skills, like emotional intelligence and strategic thinking, are best developed early in your career."},{"q":"How is African leadership different?","a":"African organizations often blend formal authority with community values, elder respect, and Ubuntu philosophy. Dr. Weah addresses these unique dynamics throughout the course rather than simply transplanting Western frameworks."},{"q":"What if I lead a small team or community organization?","a":"This course is directly applicable to any group of people, 2 to 2,000. The principles of trust, vision, accountability, and development apply equally to a village committee or a multinational corporation."},{"q":"Will this help me get promoted?","a":"Leadership skills are the most commonly cited factor in promotion decisions. This course improves your communication, decision-making, team management, and strategic thinking, all criteria by which advancement is assessed."}]};
COURSES_DB['grant-writing'] = {"id":"grant-writing","title":"Grant Writing & Fundraising","shortDesc":"Find donors, write winning proposals, and manage grants professionally, build logic models, budgets, and M&E plans that unlock funding from USAID, EU, and foundations in Liberia.","category":"Business & Fundraising","icon":"💰","gradient":"linear-gradient(135deg,#065f46,#10b981)","instructor":"Miatta S. Freeman","instructorTitle":"Grants & Partnerships Director, West Africa Impact Alliance","instructorBio":"Miatta S. Freeman has raised over $4.2 million for Liberian and West African NGOs, winning grants from USAID, the EU, UNDP, and the Mastercard Foundation. Based in Monrovia, she has trained hundreds of community organizations from Paynesville to Ganta in professional proposal development.","rating":4.8,"reviewCount":486,"students":"3,200+","duration":"30h","level":"Intermediate","price":"FREE","origPrice":"$150","isFree":true,"badge":"free","certId":"TIH-2026-GRW-0001","learn":["Understand how grants work and who funds projects in Liberia, USAID, EU, UNDP, Mastercard Foundation and more","Find real, current grant opportunities using free online databases and donor websites","Read calls for proposals correctly and judge your organization's eligibility before you apply","Build a logic model and theory of change that clearly connects activities to impact","Write compelling, data-backed needs statements about your community","Set SMART objectives and design activities donors can measure and trust","Prepare professional grant budgets in USD and LRD with realistic unit costs","Write, submit, and follow up on a complete proposal, and manage donor relationships after you win"],"requirements":["Comfortable reading and writing English at a professional level (grant proposals are written documents)","Access to a computer or smartphone with internet, a computer is strongly recommended for the capstone proposal","Basic familiarity with Word and Excel, or completion of the TIH Computer Literacy course"],"about":["Every year, millions of dollars in grant funding flows into Liberia and West Africa from donors like USAID, the European Union, UNDP, UNICEF, the Mastercard Foundation, and the Open Society Foundations. Yet many community organizations in Monrovia, Paynesville, Buchanan, and beyond never win a single grant, not because their work lacks value, but because nobody taught them how to write a proposal the way donors expect. This course fixes that.","You will move step by step through the full grant cycle: understanding who funds what, finding live opportunities, checking eligibility, building a logic model and theory of change, writing needs statements and SMART objectives, budgeting in both USD and Liberian dollars, drafting the full narrative, planning monitoring and evaluation, and managing the donor relationship after submission. The capstone challenges you to write a complete, realistic $10,000 grant proposal you can adapt and actually submit.","This is an intermediate course built on real West African examples, real donor names, real budget lines priced in Liberian markets, real reporting expectations. Whether you run a youth group in Gbarnga, a women's cooperative in Kakata, or an NGO in Sinkor, by the end you will have a fundable proposal in your hands and the confidence to keep winning."],"modules":[{"title":"Module 1: The Grant Landscape, Donors, Opportunities & Eligibility","icon":"🌍","meta":"4 lessons · 31 min","lessons":[{"t":"1.1 What Grants Are & Who Funds Them: USAID, EU, UNDP & Foundations","d":"10:00","v":"GMsl-wR-wmM"},{"t":"1.2 Finding Grant Opportunities: Databases, Calls & Donor Websites","d":"11:30","v":"tL6V3hNdbVY"},{"t":"1.3 Eligibility & Donor Priorities: Reading a Call for Proposals","d":"9:00","v":"VCvIlKM39-w"},{"t":"📝 Quiz: The Grant Landscape","d":"10 questions","isQuiz":true,"quizId":"mod1"}]},{"title":"Module 2: Designing a Fundable Project","icon":"🧩","meta":"4 lessons · 32 min","lessons":[{"t":"2.1 Logic Models & Theory of Change: From Inputs to Impact","d":"12:00","v":"lYi30bL0AMo"},{"t":"2.2 Writing a Compelling Needs Statement with Real Data","d":"10:30","v":"GH7lLHcshqQ"},{"t":"2.3 SMART Objectives & Activities Donors Can Measure","d":"9:30","v":"ENxQLZO0sRw"},{"t":"📝 Quiz: Project Design Essentials","d":"10 questions","isQuiz":true,"quizId":"mod2"}]},{"title":"Module 3: Budgets & the Full Proposal","icon":"✍️","meta":"3 lessons · 27 min","lessons":[{"t":"3.1 Grant Budgeting: Unit Costs, USD/LRD & What Donors Will Pay For","d":"13:00","v":"0nIf9hqrBzc"},{"t":"3.2 Writing the Full Proposal Narrative, Step by Step","d":"14:00","v":"ByQRri_LTUE"},{"t":"🛠️ Capstone: Write a Full $10,000 Grant Proposal","d":"Project","isProject":true}]},{"title":"Module 4: M&E, Submission & Donor Relations","icon":"🏆","meta":"3 lessons · 21 min","lessons":[{"t":"4.1 Monitoring & Evaluation Plans: Indicators, Targets & Reporting","d":"11:00","v":"Yp9VxTWMj7g"},{"t":"4.2 Submission, Follow-Up & Building Long-Term Donor Relationships","d":"9:30","v":"emhvQrFbNBA"},{"t":"📝 Quiz: M&E, Submission & Donor Relations","d":"10 questions","isQuiz":true,"quizId":"mod4"}]},{"title":"Module 5: Grant Management & Donor Compliance","icon":"📋","meta":"4 lessons · reading + quiz","lessons":[{"t":"5.1 Understanding Grant Agreements & Compliance Rules","d":"Video + notes","v":"mW4JgyCQ8EI"},{"t":"5.2 Financial Management: Receipts, Records & Spending in USD & LRD","d":"Video + notes","v":"a1uKxBaq3Jk"},{"t":"5.3 Donor Reporting: Narrative & Financial Reports That Build Trust","d":"Video + notes","v":"hvFx_gocMug"},{"t":"📝 Quiz: Grant Management & Compliance","d":"10 questions","isQuiz":true,"quizId":"mod5"}]},{"title":"Module 6: Capstone, Funding Diversification & Your Grant Writing Career","icon":"🚀","meta":"4 lessons · capstone + final","lessons":[{"t":"6.1 Diversifying Funding: Consortia, Corporate Sponsors & Crowdfunding","d":"Video + notes","v":"_OQ-qVLkJ0Y"},{"t":"6.2 Working as a Grant Writing Consultant in Liberia","d":"Video + notes","v":"_1PAOSCbzqE"},{"t":"6.3 Your Grant Writing Portfolio & Five-Year Fundraising Strategy","d":"Video + notes","v":"cyRF479o1iU"},{"t":"🏆 Final Assessment & Certificate","d":"20 questions","isQuiz":true,"quizId":"final","isFinal":true}]}],"reviews":[{"name":"Korpo Weah","loc":"Paynesville, Liberia","date":"April 2026","bg":"#065f46","init":"KW","rating":5,"text":"I lead a small women's savings group and we had never won anything before. Using the logic model and budget templates from this course, we won a $7,500 grant from a UNDP small grants window to expand our soap-making business. Miatta explains donor language in a way ordinary Liberians can understand."},{"name":"Emmanuel Togba","loc":"Ganta, Nimba County","date":"May 2026","bg":"#E31E24","init":"ET","rating":5,"text":"Our youth agriculture group in Ganta applied three times before and failed every time. After this course I rewrote our needs statement with real LISGIS data and fixed our budget with proper unit costs. We just signed our first grant agreement worth $10,000. This free course paid for itself many times over."},{"name":"Bendu Sherman","loc":"Sinkor, Monrovia","date":"March 2026","bg":"#7c3aed","init":"BS","rating":5,"text":"I work for a local NGO and was always afraid of the M&E section. The module on indicators and reporting changed everything, our program officer at the embassy praised our last report. I have since been promoted to Grants Officer with a salary increase. Thank you TIH."},{"name":"Prince Dolo","loc":"Buchanan, Grand Bassa","date":"June 2026","bg":"#0369a1","init":"PD","rating":4,"text":"The capstone was hard work but worth it. I wrote a full proposal for a school sanitation project in Buchanan and used it to apply to two foundations. One shortlisted us and requested a site visit. My only wish is for more videos on EU applications specifically, but the fundamentals here are excellent."}],"faqs":[{"q":"Is this course really free, and do I get a certificate?","a":"Yes, completely free, no credit card required. When you pass the final assessment you receive a verifiable TIH certificate (ID format TIH-2026-GRW-XXXX) that you can show to employers, NGOs, and donor-funded projects hiring grants staff."},{"q":"Do I need to work for a registered NGO to benefit?","a":"No. The course serves NGO staff, community group leaders, students, and freelancers. Grant writing is also a paid skill, many Liberian organizations hire consultants to write proposals, and this course prepares you for that work."},{"q":"Will this help me win grants specifically in Liberia?","a":"Yes. Every module uses West African examples: donors active in Liberia (USAID, EU, UNDP, UNICEF, Mastercard Foundation), budgets in USD and LRD, mobile money considerations, and the realities of community projects in Monrovia and the counties."},{"q":"How long does the course take and what is the capstone?","a":"About 20 hours total, most learners finish in 3-4 weeks studying an hour a day. The capstone asks you to write a complete, realistic $10,000 grant proposal (needs statement, logic model, objectives, budget, and M&E plan) that you can adapt and submit to a real donor."}]};
COURSES_DB['financial-literacy'] = {"id":"financial-literacy","title":"Financial Literacy: Master Your Money & Build Wealth","shortDesc":"Learn to budget in both USD and LRD, save through susu clubs and banks, use Orange Money and MTN MoMo safely, borrow wisely, and start building wealth, practical money skills for real Liberian life.","category":"Business & Finance","icon":"🏦","gradient":"linear-gradient(135deg,#0f766e,#14b8a6)","instructor":"Hawa Konneh","instructorTitle":"Financial Inclusion Specialist & Former Microfinance Officer, Monrovia","instructorBio":"Hawa Konneh spent 12 years as a microfinance and savings-group officer in Monrovia and Bong County, helping over 5,000 market traders, susu club members, and small business owners manage money across USD and LRD. She has trained financial literacy facilitators for NGOs across West Africa and designed this course around the real money challenges Liberian families face every day.","rating":4.8,"reviewCount":892,"students":"5,600+","duration":"28h","level":"All Levels","price":"FREE","origPrice":"$95","isFree":true,"badge":"free","certId":"TIH-2026-FIN-0001","learn":["Set clear financial goals and build a healthy money mindset","Create a realistic monthly budget in both USD and LRD","Track every expense using your phone, a notebook, or free apps","Use Orange Money and Lonestar Cell MTN MoMo safely and spot fraud before it happens","Save consistently through susu clubs, bank accounts, and personal savings plans","Open and manage a bank account in Liberia with confidence","Borrow wisely, avoid dangerous debt, and understand loans and interest","Build an emergency fund and a 6-month financial plan for your family"],"requirements":["No prior financial knowledge needed, we start from the very beginning","A phone or notebook to practice budgeting and expense tracking exercises","Willingness to honestly examine your own income and spending habits"],"about":["Money touches every part of life in Liberia, from paying school fees and buying rice, to sending mobile money to family upcountry, to saving for a business at Waterside or Red Light Market. Yet most of us were never taught how money actually works. This course changes that. It is built specifically for the Liberian and West African reality: two currencies, cash-heavy markets, susu clubs, mobile money, and family responsibilities.","You will learn step by step how to set financial goals, budget in USD and LRD, track your spending, protect yourself from Orange Money and MoMo fraud, save through both traditional susu clubs and formal banks, borrow without falling into debt traps, and take your first steps toward investing and building business capital.","Whether you are a student, a market trader, a motorbike rider, an office worker, or a parent managing a household, these skills will put money under your control instead of the other way around. The course is completely free, and you earn a verifiable TIH certificate when you pass the final assessment."],"modules":[{"title":"Module 1: Money Mindset & Budgeting Basics","icon":"💰","meta":"4 lessons · 32 min","lessons":[{"t":"1.1 Money Mindset & Setting Financial Goals","d":"10:00","v":"2uNvA48yvv0"},{"t":"1.2 Budgeting Basics: Managing USD & LRD Together","d":"12:30","v":"Pau88PAPD7Q"},{"t":"1.3 Tracking Your Expenses Every Day","d":"9:00","v":"ZmthxqxuFQI"},{"t":"📝 Quiz: Money Mindset & Budgeting","d":"10 questions","isQuiz":true,"quizId":"mod1"}]},{"title":"Module 2: Mobile Money, Saving & Banking","icon":"📱","meta":"4 lessons · 31 min","lessons":[{"t":"2.1 Mobile Money Mastery & Fraud Protection (Orange Money & MTN MoMo)","d":"11:00","v":"2C7u8onP7t4"},{"t":"2.2 Saving Strategies & Susu Clubs","d":"10:30","v":"nQEEQKgX6hg"},{"t":"2.3 Banking in Liberia: Accounts, Requirements & Choosing a Bank","d":"9:30","v":"guAaA1-CxT4"},{"t":"📝 Quiz: Mobile Money, Saving & Banking","d":"10 questions","isQuiz":true,"quizId":"mod2"}]},{"title":"Module 3: Debt, Credit & Borrowing Wisely","icon":"🤝","meta":"3 lessons · 22 min","lessons":[{"t":"3.1 Debt & Borrowing Wisely: Good Debt vs Bad Debt","d":"12:00","v":"wSqtotgaNAc"},{"t":"3.2 Building Credit & Understanding Loans","d":"10:00","v":"IFxzKqMFeE0"},{"t":"🛠️ Capstone: Create Your 6-Month Budget & Savings Plan","d":"Project","isProject":true}]},{"title":"Module 4: Investing & Planning Your Future","icon":"🏆","meta":"3 lessons · 24 min","lessons":[{"t":"4.1 Introduction to Investing & Building Business Capital","d":"13:00","v":"qIw-yFC-HNU"},{"t":"4.2 Financial Planning for Family & Emergencies","d":"11:00","v":"s3v2nNT7Um8"},{"t":"📝 Quiz: Investing & Planning Your Future","d":"10 questions","isQuiz":true,"quizId":"mod4"}]},{"title":"Module 5: Money & Small Business, Making Your Income Grow","icon":"🛒","meta":"4 lessons · reading + quiz","lessons":[{"t":"5.1 From Savings to Startup: Raising & Protecting Business Capital","d":"Video + notes","v":"USkACkbmRi4"},{"t":"5.2 Pricing, Profit & Simple Record-Keeping for Traders","d":"Video + notes","v":"LCW387dqgvA"},{"t":"5.3 Beyond the Basics: Agent Banking, Microfinance & Village Savings Groups","d":"Video + notes","v":"CbEeC8xXdZ8"},{"t":"📝 Quiz: Small Business Money Skills","d":"10 questions","isQuiz":true,"quizId":"mod5"}]},{"title":"Module 6: Capstone, Protecting Wealth & Leading Your Family's Financial Future","icon":"🛡️","meta":"4 lessons · capstone + final","lessons":[{"t":"6.1 Insurance & Protecting What You Build","d":"Video + notes","v":"i4FAekxeS_o"},{"t":"6.2 Land, Housing & Long-Term Assets in Liberia","d":"Video + notes","v":"AWof6O0vp3o"},{"t":"6.3 Your Complete Family Financial Plan & Teaching Money Skills","d":"Video + notes","v":"ZbtgBp4X3ZE"},{"t":"🏆 Final Assessment & Certificate","d":"20 questions","isQuiz":true,"quizId":"final","isFinal":true}]}],"reviews":[{"name":"Princess Doe","loc":"Paynesville, Liberia","date":"April 2026","bg":"#0f766e","init":"PD","rating":5,"text":"I sell at Red Light Market and I always wondered where my profit was going. After the budgeting and expense tracking lessons, I found I was losing over LD 4,000 every week on small small things. In three months I saved enough to add a second table of goods. This course is pure gold for market women."},{"name":"Emmanuel Togba","loc":"Monrovia, Liberia","date":"March 2026","bg":"#E31E24","init":"ET","rating":5,"text":"The mobile money fraud lesson saved me real money. One week after finishing it, a man called pretending to be Orange Money support asking for my PIN to reverse a transfer. I recognized the scam immediately and reported him. I also finally opened my first bank account using the checklist from Module 2."},{"name":"Musu Kollie","loc":"Kakata, Margibi County","date":"May 2026","bg":"#10b981","init":"MK","rating":5,"text":"Our susu club used to run on memory alone and we had plenty confusion. I used what I learned to set up written records and clear rules for our 12 members. Nobody has missed a payment since. The capstone project also gave me a real 6-month savings plan for my children's school fees."},{"name":"Abraham Freeman","loc":"Ganta, Nimba County","date":"June 2026","bg":"#7c3aed","init":"AF","rating":4,"text":"As a motorbike rider my income changes every day, and I thought budgeting was only for salary people. This course showed me how to budget with irregular income in both LRD and USD. I now have my first emergency fund, one month of expenses saved, and I am working toward three. Very practical teaching."}],"faqs":[{"q":"Is this course really free?","a":"Yes, 100% free. TIH believes financial literacy is a basic life skill every Liberian deserves, regardless of income. There are no hidden fees and no credit card is required."},{"q":"I don't have a bank account or much money. Can I still benefit?","a":"Absolutely, this course is designed for you. It starts with skills that need no bank account: goal setting, budgeting, expense tracking, mobile money safety, and susu savings. Banking is covered step by step for when you are ready."},{"q":"Does the course use Liberian examples or foreign ones?","a":"Every module is grounded in Liberian reality: budgeting across USD and LRD, Orange Money and Lonestar Cell MTN MoMo, susu clubs, Monrovia market trading, and banking requirements in Liberia. Video lessons are supplemented with locally focused reading notes."},{"q":"How long does it take and is the certificate recognized?","a":"Most learners finish in 3-4 weeks studying about an hour a day. Your TIH certificate includes a unique verification code (TIH-2026-FIN-0001 series) that employers, NGOs, and microfinance institutions can confirm online."}]};
COURSES_DB['english-success'] = {"id":"english-success","title":"English for Academic & Professional Success","shortDesc":"Master the formal English that opens doors, write winning scholarship essays, prepare for IELTS with proven band strategies, and speak with confidence in interviews.","category":"Language & Communication","icon":"🗣️","gradient":"linear-gradient(135deg,#4338ca,#6366f1)","instructor":"Hawa D. Cooper","instructorTitle":"English Language & Test Prep Lead, Tolbert Innovation Hub","instructorBio":"Hawa D. Cooper is a British Council-trained English instructor and former lecturer at the University of Liberia with an IELTS band 8.5. Over the past decade she has coached hundreds of Liberian and West African students to IELTS success and helped them win scholarships to universities in India, Cyprus, and Turkey.","rating":4.8,"reviewCount":612,"students":"3,200+","duration":"30h","level":"Intermediate","price":"FREE","origPrice":"$150","isFree":true,"badge":"free","certId":"TIH-2026-ENG-0001","learn":["Switch confidently between Liberian conversational English and formal international English","Apply the grammar rules that matter most in formal writing, tenses, agreement, and articles","Structure clear academic essays with strong thesis statements and paragraphs","Write scholarship personal statements and motivation letters that stand out","Understand the IELTS exam format, band scores, and how to set a realistic target","Use proven tactics for IELTS and TOEFL listening and reading sections","Plan and write high-scoring IELTS Writing Task 2 essays under time pressure","Communicate professionally in emails, workplace settings, and job interviews"],"requirements":["Intermediate English ability, a WASSCE English pass or equivalent everyday fluency is enough","A notebook and a device with internet access for video lessons and writing practice","Willingness to write, record yourself speaking, and practice aloud every week"],"about":["English is the official language of Liberia, yet many bright WASSCE graduates lose scholarships, jobs, and admission offers because the formal English expected by international examiners, universities, and employers differs from the Liberian English we speak every day at home and in the market. This course bridges that exact gap. It was built for Liberian and West African youth who already communicate in English but need to write, test, and interview at an international standard.","Across four modules you will move from register and grammar fundamentals to academic essay writing, scholarship personal statements, complete IELTS preparation, listening, reading, writing, and speaking, and finally professional emails and job interview English. Every lesson uses examples drawn from real Liberian life: applying from Monrovia, writing to admissions offices abroad, and interviewing with NGOs and companies at home.","TIH students use these exact skills to win placements at our partner destinations in India, Cyprus, and Turkey, and to secure competitive roles in Liberia. Whether your goal is an IELTS band 6.5, a Türkiye Burslari scholarship, or simply emails your boss admires, this free course gives you a clear, practical path, finishing with a capstone project and a verified TIH certificate."],"modules":[{"title":"Module 1: Foundations of Formal English","icon":"✍️","meta":"4 lessons · 33 min","lessons":[{"t":"1.1 Professional vs Conversational English: Knowing When to Switch","d":"10:00","v":"4AetJ7xJTdw"},{"t":"1.2 Grammar Essentials for Formal Writing","d":"12:00","v":"BBVsrdwuLeE"},{"t":"1.3 Academic Essay Structure: Thesis, Body & Conclusion","d":"11:00","v":"tBAbIobh3uo"},{"t":"📝 Quiz: Formal English Foundations","d":"10 questions","isQuiz":true,"quizId":"mod1"}]},{"title":"Module 2: Scholarship Writing & IELTS Foundations","icon":"🎓","meta":"4 lessons · 35 min","lessons":[{"t":"2.1 Scholarship Personal Statements & Motivation Letters","d":"12:00","v":"ZNOJ1RSJa4c"},{"t":"2.2 IELTS Overview: Format, Band Scores & Setting Your Target","d":"9:30","v":"zBLsjez-D3s"},{"t":"2.3 IELTS & TOEFL Listening and Reading Tactics","d":"13:00","v":"q8qmJeBxk4Q"},{"t":"📝 Quiz: Scholarships & IELTS Basics","d":"10 questions","isQuiz":true,"quizId":"mod2"}]},{"title":"Module 3: IELTS Writing & Confident Speaking","icon":"🎤","meta":"3 lessons · 24 min","lessons":[{"t":"3.1 IELTS Writing Task Strategies: Planning to Band 7","d":"14:00","v":"gsEmGSVU7cA"},{"t":"3.2 Speaking Confidently: Fluency & Pronunciation for International Audiences","d":"10:00","v":"edmfgGseslg"},{"t":"🛠️ Capstone: Record Your 3-Minute Professional Introduction","d":"Project","isProject":true}]},{"title":"Module 4: Professional Communication & Career English","icon":"💼","meta":"3 lessons · 24 min","lessons":[{"t":"4.1 Professional Emails & Workplace Communication","d":"11:00","v":"3Tu1jN65slw"},{"t":"4.2 Job Interview English: Presenting Yourself with Impact","d":"12:30","v":"GlN51CS_udI"},{"t":"📝 Quiz: Professional Communication & Career English","d":"10 questions","isQuiz":true,"quizId":"mod4"}]},{"title":"Module 5: Business English in the Workplace","icon":"📊","meta":"4 lessons · reading + quiz","lessons":[{"t":"5.1 Writing Reports, Memos & Meeting Minutes","d":"Video + notes","v":"ralOdKh2eAw"},{"t":"5.2 Presentations & Public Speaking in Professional English","d":"Video + notes","v":"A2TwNWiYIMI"},{"t":"5.3 Meetings, Negotiations & Phone or Video Call English","d":"Video + notes","v":"-3mFnAk9sbw"},{"t":"📝 Quiz: Business English in the Workplace","d":"10 questions","isQuiz":true,"quizId":"mod5"}]},{"title":"Module 6: Career Capstone, Your Professional English Portfolio","icon":"💼","meta":"4 lessons · capstone + final","lessons":[{"t":"6.1 CVs & Cover Letters That Win Interviews","d":"Video + notes","v":"PAthQKLhBTs"},{"t":"6.2 Networking English: LinkedIn & Professional Relationships","d":"Video + notes","v":"u03GxFNE-5Y"},{"t":"6.3 Your Professional English Portfolio & Lifelong Improvement Plan","d":"Video + notes","v":"xi2aBP0LnV4"},{"t":"🏆 Final Assessment & Certificate","d":"20 questions","isQuiz":true,"quizId":"final","isFinal":true}]}],"reviews":[{"name":"Princess Weah","loc":"Sinkor, Monrovia","date":"February 2026","bg":"#4338ca","init":"PW","rating":5,"text":"I took IELTS twice before and stayed on band 5.5. After finishing this course and following Ms. Cooper's writing strategies, I scored an overall band 7.0! My admission to a university in Cyprus is now confirmed. The lesson on Liberian English versus formal English opened my eyes completely."},{"name":"Emmanuel Dolo","loc":"Paynesville, Liberia","date":"March 2026","bg":"#E31E24","init":"ED","rating":5,"text":"The motivation letter module is gold. I rewrote my personal statement using the exact structure taught here and won a Study in India scholarship for my engineering degree. Two of my friends from my WASSCE class are now taking the course because of my result."},{"name":"Musu Fahnbulleh","loc":"Kakata, Margibi County","date":"April 2026","bg":"#10b981","init":"MF","rating":5,"text":"I was not applying abroad, I just wanted a better job here. The email and interview modules changed how I present myself. Last month I passed an interview with an international NGO in Monrovia and got the program assistant role. The capstone recording exercise gave me real confidence."},{"name":"Abraham Togba","loc":"Ganta, Nimba County","date":"May 2026","bg":"#7c3aed","init":"AT","rating":4,"text":"Studying from Nimba with limited data was my worry, but the lessons are short and practical. I scored band 6.5 on my first IELTS attempt and my Türkiye Burslari application has moved to the interview stage. I wish there were more speaking practice partners, but the content itself is excellent."}],"faqs":[{"q":"I already speak English every day in Liberia. Why do I need this course?","a":"Liberian English is rich and expressive, but international examiners, universities, and employers expect formal standard English with different grammar, vocabulary, and tone. This course teaches you exactly where the two differ and how to switch confidently, without losing your own voice."},{"q":"Will this course fully prepare me for the IELTS exam?","a":"It covers the complete IELTS foundation: format, band scoring, and strategies for all four papers, with extra depth on Writing Task 2 and Speaking. Combine it with the free official practice tests we link in each lesson, and most students are exam-ready in 6 to 10 weeks."},{"q":"Do scholarships to India, Cyprus, and Turkey always require IELTS?","a":"Requirements vary. Some partner universities accept a WASSCE English pass or their own English interview, while others require IELTS 6.0 to 6.5. This course prepares you for all three paths, the test, the written application, and the interview, so no requirement catches you off guard."},{"q":"Is the certificate useful if I stay and work in Liberia?","a":"Yes. Strong formal English is one of the most requested skills by employers and NGOs in Monrovia and across the counties. Your TIH certificate carries a unique verification code that Liberian employers can confirm instantly, and the email and interview skills apply to any job application at home."}]};
COURSES_DB['agritech'] = {"id":"agritech","title":"AgriTech & Digital Agriculture","shortDesc":"See how phones, apps, and smart tools can transform farming in Liberia, from digital farm records and crop planning to selling produce online, mobile money, drones, and sensors.","category":"Agriculture & Technology","icon":"🌾","gradient":"linear-gradient(135deg,#3f6212,#84cc16)","instructor":"Kormassa Dolo","instructorTitle":"Agronomist & AgriTech Consultant, Central Agricultural Research Institute (CARI) Alumna","instructorBio":"Kormassa Dolo is a Liberian agronomist trained at Cuttington University and CARI in Suakoko, Bong County. She has spent over a decade helping smallholder rice, cassava, and vegetable farmers in Lofa, Bong, and Nimba counties adopt digital tools, from spreadsheet record keeping to WhatsApp marketing, and has consulted for agribusinesses across West Africa.","rating":4.8,"reviewCount":412,"students":"2,900+","duration":"27h","level":"Beginner","price":"FREE","origPrice":"$95","isFree":true,"badge":"free","certId":"TIH-2026-AGR-0001","learn":["Understand what AgriTech is and how it can transform Liberian farming","Keep accurate digital farm records using free phone apps and spreadsheets","Plan crops using weather forecasts and market price data","Use mobile apps and SMS services to get farming advice and market prices","Apply low-cost precision methods for soil, plant spacing, and inputs","Reduce post-harvest losses with proper handling and storage technology like hermetic bags","Sell farm produce online using WhatsApp Business and Facebook Marketplace","Manage farm money with mobile money, budgets, and simple agribusiness plans"],"requirements":["No farming or technology experience required, everything starts from the basics","A smartphone with WhatsApp (a basic phone works for the SMS and mobile money lessons)","Interest in farming, agribusiness, or helping farmers in your community"],"about":["Agriculture employs the majority of Liberians, yet most of our farmers still work without records, without market information, and without technology. Meanwhile, a young farmer in Kenya checks market prices by SMS and a rice processor like Fabrar Rice in Liberia uses modern milling and packaging to compete with imported rice. This course closes that gap, it shows Liberian and West African youth how simple, affordable technology can make farming more profitable and less risky.","You will learn practical digital skills built for our reality: keeping farm records on a phone, planning cassava and vegetable planting around the rainy season and Monrovia market prices, storing rice in hermetic bags so weevils do not eat your profit, selling greens and peppers to Monrovia buyers on WhatsApp, and receiving payment safely with Lonestar MTN Mobile Money or Orange Money. Every example uses Liberian crops, rice, cassava, rubber, cocoa, and vegetables, and real markets like Red Light and Duala.","Whether you farm in Lofa, run a small garden in Paynesville, or dream of starting an agribusiness, this course gives you a complete foundation. You will finish with a capstone project, a digital farm record and marketing plan you can use immediately, plus a verified TIH certificate recognized by employers, NGOs, and agricultural programs."],"modules":[{"title":"Module 1: AgriTech Foundations & Farm Data","icon":"🌾","meta":"4 lessons · 34 min","lessons":[{"t":"1.1 What is AgriTech? Why It Matters for Liberia","d":"10:00","v":"ev-4uQzdTXI"},{"t":"1.2 Digital Farm Record Keeping with Phone Apps & Spreadsheets","d":"11:30","v":"QijsZjlvxh4"},{"t":"1.3 Smart Crop Planning with Weather & Market Data","d":"12:00","v":"l8nFgIhK7bw"},{"t":"📝 Quiz: AgriTech Foundations","d":"10 questions","isQuiz":true,"quizId":"mod1"}]},{"title":"Module 2: Digital Tools for the Field","icon":"📱","meta":"4 lessons · 32 min","lessons":[{"t":"2.1 Mobile Apps & SMS Services for Farmers","d":"9:30","v":"yoeVcRlj1WI"},{"t":"2.2 Precision Basics: Soil, Spacing & Inputs on a Budget","d":"12:30","v":"GcPdvSj6CbE"},{"t":"2.3 Post-Harvest Handling & Storage Technology","d":"10:00","v":"dsYo9rBPQGo"},{"t":"📝 Quiz: Digital Tools for the Field","d":"10 questions","isQuiz":true,"quizId":"mod2"}]},{"title":"Module 3: Selling & Managing Farm Money Online","icon":"💰","meta":"3 lessons · 20 min","lessons":[{"t":"3.1 Selling Farm Produce Online: WhatsApp Business & Facebook Marketplace","d":"11:00","v":"gHfEm1z-3iY"},{"t":"3.2 Farm Finance & Mobile Money for Agribusiness","d":"9:00","v":"pun14jec_Xk"},{"t":"🛠️ Capstone: Build a Digital Farm Record & Marketing Plan","d":"Project","isProject":true}]},{"title":"Module 4: Agri-Entrepreneurship & The Future","icon":"🏆","meta":"3 lessons · 26 min","lessons":[{"t":"4.1 Agri-Entrepreneurship & Value Addition","d":"12:00","v":"EEcy1swBlRo"},{"t":"4.2 Drones, Sensors & The Future of Farming","d":"14:00","v":"qwNVNE83Udo"},{"t":"📝 Quiz: Agri-Entrepreneurship & The Future of Farming","d":"10 questions","isQuiz":true,"quizId":"mod4"}]},{"title":"Module 5: Value Chains, Cooperatives & Market Access","icon":"🚛","meta":"4 lessons · reading + quiz","lessons":[{"t":"5.1 Liberia's Crop Value Chains: From Farm Gate to Final Buyer","d":"Video + notes","v":"XyGtTvH_NXY"},{"t":"5.2 Cooperatives, Aggregation & Selling Together","d":"Video + notes","v":"sdMZ_HCAGO4"},{"t":"5.3 Quality, Grading & Winning Better Prices","d":"Video + notes","v":"niYA0qrUJiE"},{"t":"📝 Quiz: Value Chains, Cooperatives & Market Access","d":"10 questions","isQuiz":true,"quizId":"mod5"}]},{"title":"Module 6: Capstone, Your Agribusiness Plan & Career","icon":"🎓","meta":"4 lessons · capstone + final","lessons":[{"t":"6.1 Writing a Farm Business Plan That Wins Financing","d":"Video + notes","v":"WUvWHlCsDk4"},{"t":"6.2 Working with Extension Services, NGOs & Agri Programs","d":"Video + notes","v":"BHoG5zhPj7Y"},{"t":"6.3 Your AgriTech Portfolio: Presenting Your Capstone & Growing Your Career","d":"Video + notes","v":"WgqAejCz2gM"},{"t":"🏆 Final Assessment & Certificate","d":"20 questions","isQuiz":true,"quizId":"final","isFinal":true}]}],"reviews":[{"name":"Korto Weah","loc":"Voinjama, Lofa County","date":"March 2026","bg":"#3f6212","init":"KW","rating":5,"text":"My family grows rice and I never knew our real profit until this course. I set up a Google Sheets record and found we were losing money on transport. This season I organized shared transport with neighbors and stored paddy in hermetic bags, we saved almost LRD 40,000. Every young farmer in Lofa should take this."},{"name":"Emmanuel Gonlepa","loc":"Ganta, Nimba County","date":"April 2026","bg":"#84cc16","init":"EG","rating":5,"text":"I started a WhatsApp Business catalog for my pepper and bitterball garden after Module 3. Now I have regular buyers from Ganta and even two restaurants in Monrovia who pay me through Mobile Money before I even harvest. My income has more than doubled in three months."},{"name":"Musu Fahnbulleh","loc":"Kakata, Margibi County","date":"May 2026","bg":"#0891b2","init":"MF","rating":5,"text":"The value addition lesson changed my thinking. Instead of selling raw cassava at Red Light, I now process it into fufu flour and package it in small bags. The capstone project became my real business plan and I used it to win a small youth agribusiness grant."},{"name":"Abraham Togba","loc":"Gbarnga, Bong County","date":"June 2026","bg":"#7c3aed","init":"AT","rating":4,"text":"I am an agriculture student at Cuttington and this course taught practical things my classes never covered, checking weather data before planting and using SMS market services. The certificate verification impressed the NGO where I now intern as a farmer field assistant."}],"faqs":[{"q":"Do I need to own a farm to take this course?","a":"No. This course is for anyone interested in agriculture, students, aspiring agri-entrepreneurs, extension workers, or family members who help on a farm. The skills also prepare you for jobs with NGOs and agribusinesses."},{"q":"Will these tools work in rural areas with poor internet?","a":"Yes. The course emphasizes tools that work in low-connectivity settings, SMS and USSD services on basic phones, offline spreadsheet apps, and mobile money which works without internet. Lessons can be downloaded when you have connection."},{"q":"Is this course really free and do I get a certificate?","a":"Completely free, no hidden costs. When you pass the final assessment you receive a TIH certificate with a unique verification code (TIH-2026-AGR series) that employers, NGOs, and agricultural programs can verify online."},{"q":"Which crops does the course cover?","a":"Examples focus on Liberia's main crops, rice, cassava, vegetables, rubber, and cocoa, but every method (record keeping, storage, online selling, mobile money) applies to any crop or livestock enterprise in West Africa."}]};
COURSES_DB['healthtech'] = {"id":"healthtech","title":"Healthcare Technology & Telehealth","shortDesc":"Digital skills for modern health work, electronic records, telehealth, patient follow-up, and health data privacy, built for Liberian clinics and community health workers.","category":"Health & Technology","icon":"🏥","gradient":"linear-gradient(135deg,#9f1239,#f43f5e)","instructor":"Dr. Musu Kollie-Nagbe","instructorTitle":"Health Informatics Specialist & Digital Health Consultant, Monrovia","instructorBio":"Dr. Musu Kollie-Nagbe is a Liberian health informatics specialist who served in the Ministry of Health data systems team during the 2014-2016 Ebola response and later supported DHIS2 reporting rollouts across county health teams. She has trained nurses, physician assistants, and community health assistants at JFK Medical Center, Redemption Hospital, and rural facilities in Bong, Nimba, and Lofa to move from paper to digital workflows.","rating":4.8,"reviewCount":318,"students":"2,300+","duration":"27h","level":"Beginner","price":"FREE","origPrice":"$150","isFree":true,"badge":"free","certId":"TIH-2026-HLT-0001","learn":["Explain what digital health is and why it matters for African health systems","Compare electronic health records with paper systems and plan a safe transition","Build digital patient intake forms using Google Forms and KoboToolbox","Conduct professional telehealth consultations by phone, video, and chat","Run patient follow-up programs using SMS and WhatsApp on Lonestar and Orange networks","Protect patient privacy and confidentiality when handling digital health data","Understand how DHIS2 and community health worker tools support MOH reporting","Use simple digital tools to manage clinic appointments, records, and drug inventory"],"requirements":["No prior health informatics or IT experience needed, this course starts from the basics","Access to a smartphone or computer with internet (mobile data on Lonestar or Orange is enough)","Helpful but not required: experience in or interest in a clinic, hospital, pharmacy, or community health role"],"about":["Health care in Liberia and across West Africa is going digital. From DHIS2 reporting at county health teams to WhatsApp follow-up between community health assistants and district supervisors, the health workers who can use digital tools are the ones being hired, promoted, and trusted with bigger responsibilities. Yet most facilities, from JFK Medical Center in Sinkor to small clinics in Lofa and Grand Gedeh, still run on paper records that get lost, damaged, or duplicated.","This course teaches you the practical digital skills that health facilities actually need: replacing paper registers with electronic records, building digital patient intake forms with free tools like Google Forms and KoboToolbox, running remote consultations by phone and video, following up with patients over SMS and WhatsApp, protecting patient confidentiality, and tracking drug inventory so clinics stop running out of essential medicines. Every lesson uses real Liberian examples, including the hard lessons the country learned about health data during the Ebola crisis.","Whether you are a nurse, physician assistant, community health assistant (CHA), pharmacy worker, records clerk, health sciences student, or a tech-minded person who wants to serve the health sector, this free course gives you a verified certificate and a capstone project you can show to employers, county health teams, and NGOs."],"modules":[{"title":"Module 1: Foundations of Digital Health","icon":"🏥","meta":"4 lessons · 34 min","lessons":[{"t":"1.1 Introduction to Health Technology & Digital Health in Africa","d":"11:00","v":"_EqfLDZc28Q"},{"t":"1.2 Electronic Health Records vs Paper Systems","d":"9:30","v":"HoWvf76JdX8"},{"t":"1.3 Digital Patient Intake Forms with Google Forms & KoboToolbox","d":"13:00","v":"9ewgr1BD0Rw"},{"t":"📝 Quiz: Digital Health Foundations","d":"10 questions","isQuiz":true,"quizId":"mod1"}]},{"title":"Module 2: Telehealth & Mobile Health in Practice","icon":"📱","meta":"4 lessons · 31 min","lessons":[{"t":"2.1 Telehealth Fundamentals & Remote Consultations","d":"10:00","v":"2xuNOPU3zhg"},{"t":"2.2 mHealth: SMS & WhatsApp for Patient Follow-Up","d":"12:00","v":"Qus5MFg-tDk"},{"t":"2.3 Health Data Privacy & Confidentiality Basics","d":"8:30","v":"Lfhl0ip14CI"},{"t":"📝 Quiz: Telehealth & Patient Privacy","d":"10 questions","isQuiz":true,"quizId":"mod2"}]},{"title":"Module 3: Digital Tools for Community & Public Health","icon":"🧑‍⚕️","meta":"3 lessons · 21 min","lessons":[{"t":"3.1 Community Health Worker Digital Tools & DHIS2 Awareness","d":"11:30","v":"V0Nt395JQQg"},{"t":"3.2 Health Information for Patients: Fighting Misinformation Online","d":"9:00","v":"n4ga1YzwWNY"},{"t":"🛠️ Capstone: Design a Digital Patient Intake & Telehealth Workflow","d":"Project","isProject":true}]},{"title":"Module 4: Clinic Operations & Your Health Tech Career","icon":"🏆","meta":"3 lessons · 25 min","lessons":[{"t":"4.1 Digital Tools for Clinic Management & Inventory","d":"14:00","v":"WOXrMOzK_A4"},{"t":"4.2 Careers in Health Tech & Telemedicine in West Africa","d":"10:30","v":"SkzILojGPos"},{"t":"📝 Quiz: Clinic Operations & Health Tech Careers","d":"10 questions","isQuiz":true,"quizId":"mod4"}]},{"title":"Module 5: Health Data, Reporting & Quality in Practice","icon":"📊","meta":"4 lessons · reading + quiz","lessons":[{"t":"5.1 Health Indicators & the Reporting Chain: From Register to DHIS2","d":"Video + notes","v":"MRLAyC5L2Rg"},{"t":"5.2 Data Quality: Making Health Data Accurate, Complete & Timely","d":"Video + notes","v":"GWiiZWb69Sw"},{"t":"5.3 Analyzing Clinic Data with Spreadsheets: From Numbers to Decisions","d":"Video + notes","v":"aofsdpjvK7w"},{"t":"📝 Quiz: Health Data, Reporting & Quality","d":"10 questions","isQuiz":true,"quizId":"mod5"}]},{"title":"Module 6: Capstone, Leading Digital Change in Your Facility","icon":"🎓","meta":"4 lessons · capstone + final","lessons":[{"t":"6.1 Planning a Paper-to-Digital Project: Scope, Pilot & Rollout","d":"Video + notes","v":"NAFSRKYJTjM"},{"t":"6.2 Bringing People Along: Training Colleagues & Managing Resistance","d":"Video + notes","v":"7oqFhxXHI7A"},{"t":"6.3 Your Health Tech Portfolio & Career Roadmap","d":"Video + notes","v":"_5nWyEAFl2M"},{"t":"🏆 Final Assessment & Certificate","d":"20 questions","isQuiz":true,"quizId":"final","isFinal":true}]}],"reviews":[{"name":"Korpo Weah","loc":"Paynesville, Liberia","date":"April 2026","bg":"#9f1239","init":"KW","rating":5,"text":"I am a records clerk at a private clinic in Paynesville. After Module 1, I built our first digital intake form in KoboToolbox and we digitized three years of patient files in two months. Our doctor now finds any patient history in seconds. My supervisor gave me a new title: Health Records Officer."},{"name":"Emmanuel Dolo","loc":"Ganta, Nimba County","date":"March 2026","bg":"#002868","init":"ED","rating":5,"text":"As a community health assistant, I used to walk hours to hand in paper reports. This course taught me how our data feeds into DHIS2 and how to do patient follow-up by SMS on the Lonestar network. My defaulter tracing for TB patients improved so much that the county health team asked me to train other CHAs."},{"name":"Princess Toe","loc":"Monrovia, Liberia","date":"May 2026","bg":"#10b981","init":"PT","rating":5,"text":"I am a nurse and I always feared technology. Dr. Musu explains everything with examples from JFK and Redemption that I recognize from my own work. I now run phone follow-up consultations for our hypertension patients over WhatsApp, and our missed-appointment rate dropped by almost half."},{"name":"Abraham Fahnbulleh","loc":"Voinjama, Lofa County","date":"June 2026","bg":"#7c3aed","init":"AF","rating":4,"text":"Our clinic pharmacy in Lofa kept running out of essential drugs. Using the inventory lesson in Module 4, I set up a simple stock tracker on a spreadsheet and we have not had a stockout of malaria medicine since February. The capstone project became a real system we use every day. Internet in Voinjama is slow, but the lessons downloaded fine."}],"faqs":[{"q":"Do I need to be a doctor or nurse to take this course?","a":"No. This course is for anyone connected to health work, nurses, physician assistants, CHAs, pharmacy staff, records clerks, health sciences students, and tech-minded people who want to serve clinics and hospitals. No medical or IT background is required."},{"q":"Will the tools taught cost my clinic money?","a":"No. The course focuses on free tools: Google Forms, KoboToolbox, WhatsApp, SMS, and free spreadsheet software. DHIS2 is already provided by MOH Liberia to health facilities. Everything you learn can be applied with a smartphone and mobile data."},{"q":"Is patient data safe with these digital tools?","a":"Yes, when used correctly, and an entire lesson is dedicated to privacy and confidentiality. You will learn consent, need-to-know sharing, safe messaging practices, and the confidentiality standards expected by MOH Liberia and health NGOs."},{"q":"Is the certificate useful for health sector jobs?","a":"Yes. Your TIH certificate carries a unique verification code that employers can confirm online. Health facilities, county health teams, and NGOs across Liberia increasingly ask for digital skills, and your capstone project gives you real evidence to show at interviews."}]};
COURSES_DB['remote-work'] = {"id":"remote-work","title":"Remote Work & Freelancing","shortDesc":"Earn US dollars online, package your skills, win clients on Upwork and Fiverr, build a portfolio, price your work, and get paid reliably from Liberia.","category":"Remote Work & Freelancing","icon":"💼","gradient":"linear-gradient(135deg,#c2410c,#e31e24)","instructor":"Emmanuel Gaye","instructorTitle":"Remote Work Coach & Top-Rated Upwork Freelancer, TIH","instructorBio":"Emmanuel Gaye is a Top-Rated Plus Upwork freelancer who built a six-figure remote career in digital marketing and writing without ever leaving Monrovia. He has coached over 800 West African freelancers to land their first international clients and get paid reliably in USD.","rating":4.9,"reviewCount":612,"students":"3,200+","duration":"29h","level":"Intermediate","price":"FREE","origPrice":"$140","isFree":true,"badge":"free","certId":"TIH-2026-RMT-0001","learn":["Understand the global remote work market and which skills earn USD from Liberia","Identify, package, and position your most marketable skill for international clients","Build an Upwork profile and Fiverr gigs that win high-paying clients","Write proposals and cover letters that get replies and interviews","Create a professional portfolio for free using tools like Canva and Google Sites","Price your services confidently and negotiate rates in US dollars","Receive international payments in Liberia using Payoneer, Wise, and mobile money","Deliver 5-star work, earn repeat clients, and grow from solo freelancer to agency owner"],"requirements":["Basic computer and internet skills (or complete our free Computer Literacy course first)","A reliable smartphone or laptop plus a plan for managing data costs and power outages","At least one skill to offer such as writing, design, virtual assistance, or data entry (we help you find yours)"],"about":["The internet has erased the distance that once locked Liberian youth out of the global job market. Today a young person in Monrovia, Buchanan, or Gbarnga can earn United States dollars from clients in New York, London, or Nairobi without ever leaving home. This course is a complete, practical roadmap for turning your skills into real global income from right here in Liberia.","You will learn exactly how to choose a marketable skill, build a winning profile on Upwork and Fiverr, write proposals that get replies, and price your work fairly. Most importantly, this course tackles the challenge that stops most Liberians before they start: how to actually get paid. We walk through Payoneer, Wise, mobile money, and real PayPal workarounds, plus how to plan around data costs and electricity outages so you never miss a deadline.","Thousands of West African freelancers are already earning $800 to $2,000 every month online. Whether you are a student, a job seeker, or a professional wanting extra income, this free course gives you a clear, step-by-step path from your first proposal to your first paycheck and beyond, all the way to building your own small agency."],"modules":[{"title":"Module 1: The Global Remote Work Opportunity","icon":"💼","meta":"4 lessons · 40 min","lessons":[{"t":"1.1 The Remote Work Landscape: What Skills Actually Sell","d":"11:20","v":"7oM-Nfl8CtQ"},{"t":"1.2 Finding & Packaging Your Marketable Skill","d":"10:15","v":"Tn6-PIqc4UM"},{"t":"1.3 Creating an Upwork Profile That Wins Clients","d":"13:40","v":"9NzTAZPra3A"},{"t":"📝 Quiz: The Remote Work Opportunity","d":"10 questions","isQuiz":true,"quizId":"mod1"}]},{"title":"Module 2: Winning Clients & Building Your Presence","icon":"🎯","meta":"4 lessons · 40 min","lessons":[{"t":"2.1 Fiverr Gigs That Sell: Setup & Optimization","d":"12:30","v":"8gNUUK6fwX4"},{"t":"2.2 Writing Winning Proposals & Cover Letters","d":"11:45","v":"rErBcmM1wDk"},{"t":"2.3 Building a Portfolio with Free Tools","d":"10:50","v":"DvMNG6MUlGI"},{"t":"📝 Quiz: Winning Your First Clients","d":"10 questions","isQuiz":true,"quizId":"mod2"}]},{"title":"Module 3: Pricing & Getting Paid in Liberia","icon":"💰","meta":"3 lessons · 50 min","lessons":[{"t":"3.1 Pricing Your Services & Negotiating Rates","d":"12:10","v":"2GzslyLAD1E"},{"t":"3.2 Getting Paid in Liberia: Payoneer, Wise, Mobile Money & PayPal","d":"13:20","v":"9uU-i5ZI-_U"},{"t":"🛠️ Capstone: Launch Your Complete Freelance Profile & Portfolio","d":"Project","isProject":true}]},{"title":"Module 4: Delivering, Growing & Certification","icon":"🏆","meta":"3 lessons · 40 min","lessons":[{"t":"4.1 Delivering Excellent Work & Earning 5-Star Reviews","d":"9:40","v":"Tn6-PIqc4UM"},{"t":"4.2 Growing from Freelancer to Agency","d":"14:00","v":"FTOpohYyn1o"},{"t":"📝 Quiz: Delivering Excellence & Growing Your Freelance Business","d":"10 questions","isQuiz":true,"quizId":"mod4"}]},{"title":"Module 5: Client Communication, Contracts & Freelance Finances","icon":"🤝","meta":"4 lessons · reading + quiz","lessons":[{"t":"5.1 Client Communication Mastery: From Kickoff to Final Delivery","d":"Video + notes","v":"cZ_nqaptW88"},{"t":"5.2 Contracts, Scope Creep & Handling Difficult Clients","d":"Video + notes","v":"vSsVueEptN4"},{"t":"5.3 Managing Your Freelance Money: Budgeting, Fees & Reinvesting in Liberia","d":"Video + notes","v":"gw428ygPNiY"},{"t":"📝 Quiz: Client Communication, Contracts & Money","d":"10 questions","isQuiz":true,"quizId":"mod5"}]},{"title":"Module 6: Capstone, Your Freelance Business Launch","icon":"🚀","meta":"4 lessons · capstone + final","lessons":[{"t":"6.1 Positioning & Personal Brand: Becoming the Obvious Choice","d":"Video + notes","v":"rk9nCnLpreU"},{"t":"6.2 Beyond the Marketplaces: Direct Clients, Referrals & LinkedIn","d":"Video + notes","v":"d7Ms-a2Z9mY"},{"t":"6.3 The 90-Day Launch Plan: Portfolio, Targets & Your First $1,000","d":"Video + notes","v":"Oos9UXRvr28"},{"t":"🏆 Final Assessment & Certificate","d":"20 questions","isQuiz":true,"quizId":"final","isFinal":true}]}],"reviews":[{"name":"Grace Johnson","loc":"Monrovia, Liberia","date":"February 2026","bg":"#c2410c","init":"GJ","rating":5,"text":"I always thought freelancing was for people abroad. This course changed my mind completely. Within six weeks I set up my Upwork profile, sent proposals the way Emmanuel taught, and landed my first 500 dollar contract as a virtual assistant. I got paid through Payoneer with no stress. This is real income for my family."},{"name":"Prince Karweaye","loc":"Paynesville, Liberia","date":"March 2026","bg":"#e31e24","init":"PK","rating":5,"text":"The Fiverr lessons are gold. I started a logo design gig at a low price to earn reviews, and after fifteen 5-star reviews I now charge 50 dollars per order. Buyers come to me even while my data is off. I never believed I could earn dollars from Paynesville, but here I am."},{"name":"Bendu Massaquoi","loc":"Gbarnga, Bong County","date":"May 2026","bg":"#0e7490","init":"BM","rating":4,"text":"I had no portfolio and no confidence. The lesson on free tools showed me how to build sample work in Canva and put it online for free. I used one sample in a proposal and won my first international writing client. Living in Gbarnga has never stopped me since."},{"name":"Alfred Toe","loc":"Buchanan, Grand Bassa","date":"June 2026","bg":"#7c3aed","init":"AT","rating":5,"text":"Getting paid was my biggest fear, and this course solved it. The payment module walked me through Payoneer and Wise step by step. My first 500 dollar Upwork payment reached my local bank within days. Every Liberian who wants to work online needs this course."}],"faqs":[{"q":"How do I receive payment in Liberia as a freelancer?","a":"The proven setup is Payoneer for Upwork and Fiverr payouts, plus Wise for direct client bank transfers with low fees, and then withdrawing to your Liberian bank account or mobile money such as Orange Money or MTN MoMo. We show you how to open and verify each account early so your payments are never held up."},{"q":"Do I need experience or a university degree to start freelancing?","a":"No. Many successful freelancers start with no experience and no degree. This course shows you how to identify a skill you already have, create sample work to prove it, and win your first clients through strong profiles and personalized proposals."},{"q":"How do I deal with unreliable internet and electricity in Liberia?","a":"We teach practical planning: buy data bundles ahead of deadlines, keep a power bank or generator backup, and deliver work early so an outage never causes a late delivery. Fiverr gigs are also ideal because orders arrive even when you are offline."},{"q":"Is this course really free and is the certificate recognized?","a":"Yes, it is completely free with no credit card required. On passing the final assessment you receive a TIH certificate with a unique verification code that employers and clients can confirm as genuine."}]};
COURSES_DB['ielts'] = {"id":"ielts","title":"IELTS Masterclass: Band 7+ in Listening, Reading, Writing & Speaking","shortDesc":"A complete, strategy-driven IELTS course covering all four skills, the band-score system, question-type tactics, model answers, and full practice, built to move you to Band 7 and beyond.","category":"Exam Preparation","icon":"🌍","image":"ielts-banner.jpg","cardImage":"ielts-card.jpg","gradient":"linear-gradient(135deg,#0b3d91,#1e3a8a,#3b82f6)","instructor":"Samuel Tolbert","instructorTitle":"Founder & CEO, Tolbert Innovation Hub","instructorBio":"Samuel Tolbert founded TIH to bring world-class exam preparation to Liberia and West Africa, coaching hundreds of students toward the scores they need to study and work abroad.","rating":4.9,"reviewCount":512,"students":"1,200+","duration":"36h","level":"Intermediate → Advanced","price":"$50","origPrice":"$150","isFree":false,"badge":"premium","certId":"TIH-2026-IELTS-0001","learn":["Understand the Academic and General Training tests and choose the right one","Decode the 0–9 band-score system and the examiner criteria for each skill","Master every Listening question type with prediction and keyword tactics","Read faster with skimming, scanning and time control, and beat True/False/Not Given","Write Task 1 (graphs and letters) and Task 2 essays that hit Band 7 structure","Speak fluently across Parts 1–3 with model answers and pronunciation tips","Avoid the common mistakes that keep candidates stuck at Band 5–6"],"requirements":["An intermediate level of English (roughly Band 5) to build from","A notebook or device to complete the writing and speaking practice tasks","Commitment to practise with a timer, IELTS is as much about timing as accuracy"],"about":["IELTS is the world’s most widely accepted English test for university admission, professional registration, and migration. A strong band score opens doors to scholarships and opportunities across the UK, Canada, Australia, and beyond.","This masterclass is not a collection of random tips. It is a structured system: you learn how each of the four skills is scored, then work through the exact strategies for every question type, with model answers and practice built in.","Written specifically for learners in Liberia and West Africa, every lesson is clear, practical, and focused on turning effort into a higher band score."],"modules":[{"title":"Module 1: IELTS Foundations & the Band System","icon":"🧭","meta":"4 lessons","lessons":[{"t":"1.1 The IELTS Test: Academic vs General Training","d":"Reading","v":"tOFm-zoI6-w"},{"t":"1.2 Understanding the Band Score System (0–9)","d":"Reading","v":"zBLsjez-D3s"},{"t":"1.3 Test-Day Logistics & Smart Preparation","d":"Reading","v":"tIpP4M1kvvE"},{"t":"📝 Quiz: IELTS Format & Scoring","d":"5 questions","isQuiz":true,"quizId":"mod1"}]},{"title":"Module 2: Listening","icon":"🎧","meta":"4 lessons","lessons":[{"t":"2.1 The Four Sections & Every Question Type","d":"Reading","v":"q2odDqMhYOg"},{"t":"2.2 Strategies: Prediction, Keywords & Distractor Traps","d":"Reading","v":"gfTqr_9BMjs"},{"t":"2.3 Spelling, Numbers & Transferring Answers","d":"Reading","v":"RrViOflRWg0"},{"t":"📝 Quiz: Listening","d":"5 questions","isQuiz":true,"quizId":"mod2"}]},{"title":"Module 3: Reading","icon":"📖","meta":"4 lessons","lessons":[{"t":"3.1 Skimming, Scanning & Time Management","d":"Reading","v":"7etaXjWJVJg"},{"t":"3.2 True / False / Not Given (and Yes / No / Not Given)","d":"Reading","v":"cNyLs7YWFL8"},{"t":"3.3 Matching Headings, Completion & Multiple Choice","d":"Reading","v":"SXdMpskBDmA"},{"t":"📝 Quiz: Reading","d":"5 questions","isQuiz":true,"quizId":"mod3"}]},{"title":"Module 4: Writing","icon":"✍️","meta":"5 lessons","lessons":[{"t":"4.1 Task 1 Academic: Describing Graphs, Charts & Processes","d":"Reading","v":"mTDjuQ-G31I"},{"t":"4.2 Task 1 General: Formal & Informal Letters","d":"Reading","v":"TbdP4Sz5Bn0"},{"t":"4.3 Task 2: Essay Structure & Building an Argument","d":"Reading","v":"_LwCwsFDRdE"},{"t":"4.4 Cohesion, Vocabulary & Common Mistakes","d":"Reading","v":"wSbv5bCY4No"},{"t":"🛠️ Project: Write a Full Band 7 Task 2 Essay","d":"Project","isProject":true,"v":"_LwCwsFDRdE"}]},{"title":"Module 5: Speaking","icon":"🗣️","meta":"4 lessons","lessons":[{"t":"5.1 Part 1: Introduction & Interview","d":"Reading","v":"wK5mVNZGYRc"},{"t":"5.2 Part 2: The Long Turn (Cue Card)","d":"Reading","v":"BzhUwBaQK1g"},{"t":"5.3 Part 3: Discussion, Fluency & Pronunciation","d":"Reading","v":"QoeKYAqBRtE"}]},{"title":"Module 6: Vocabulary, Grammar & Your Band 7+ Plan","lessons":[{"t":"6.1 Vocabulary for Band 7+: Collocations & Precision","d":"Video + notes","v":"lhDpoCYmnNQ"},{"t":"6.2 Grammar Range: Complex Sentences Without Errors","d":"Video + notes","v":"h9fxF0LKRyY"},{"t":"6.3 The Full Mock Test: Practice Under Real Exam Conditions","d":"Video + notes","v":"NXJa7GFjY3U"},{"t":"6.4 Your 30-Day Study Plan & Test-Week Checklist","d":"Video + notes","v":"3nrujcxJSNs"},{"t":"📝 Quiz: Vocabulary, Grammar & Strategy","d":"8 questions","isQuiz":true,"quizId":"mod6"},{"t":"🏆 Final Assessment & Certificate","d":"Assessment","isQuiz":true,"quizId":"final","isFinal":true}],"icon":"🎓","meta":"6 lessons"}]};
COURSES_DB['toefl'] = {"id":"toefl","title":"TOEFL iBT Masterclass: Reading, Listening, Speaking & Writing","shortDesc":"A complete TOEFL iBT preparation course covering the format and 1–120 scoring, all four sections, integrated tasks, templates, and model responses to reach a competitive score.","category":"Exam Preparation","icon":"🎓","image":"toefl-banner.jpg","cardImage":"toefl-card.jpg","gradient":"linear-gradient(135deg,#7c2d12,#b45309,#f59e0b)","instructor":"Samuel Tolbert","instructorTitle":"Founder & CEO, Tolbert Innovation Hub","instructorBio":"Samuel Tolbert founded TIH to bring world-class exam preparation to Liberia and West Africa, helping students meet the TOEFL scores required by universities worldwide.","rating":4.9,"reviewCount":388,"students":"900+","duration":"34h","level":"Intermediate → Advanced","price":"$25","origPrice":"$150","isFree":false,"badge":"premium","certId":"TIH-2026-TOEFL-0001","learn":["Understand the TOEFL iBT format and the 0–120 scoring scale","Read academic passages efficiently and master every question type","Take effective notes for the Listening section lectures and conversations","Deliver strong independent and integrated Speaking responses using templates","Write the Integrated and Academic Discussion tasks to a high standard","Manage timing and stress across the full test"],"requirements":["An intermediate level of English to build from","A headset or quiet space to practise Speaking responses out loud","Willingness to practise note-taking, which is central to TOEFL success"],"about":["The TOEFL iBT is accepted by more than 11,000 universities worldwide and is often required for admission and scholarships in the United States and beyond.","This masterclass breaks the test into its four sections and teaches a reliable method for each, including the integrated tasks that combine reading, listening and speaking or writing, which most candidates find hardest.","Every lesson is written for clarity and built around templates and model answers you can adapt on test day."],"modules":[{"title":"Module 1: TOEFL iBT Foundations","icon":"🧭","meta":"3 lessons","lessons":[{"t":"1.1 The TOEFL iBT Format & the 0–120 Score","d":"Reading","v":"i8p28izQNdQ"},{"t":"1.2 How Each Section Is Scored & What Universities Want","d":"Reading","v":"fGrxgRAISlM"},{"t":"📝 Quiz: TOEFL Format & Scoring","d":"5 questions","isQuiz":true,"quizId":"mod1"}]},{"title":"Module 2: Reading","icon":"📖","meta":"3 lessons","lessons":[{"t":"2.1 Academic Passages & the 10 Question Types","d":"Reading","v":"UrsAfqDc_jI"},{"t":"2.2 Strategy: Vocabulary, Inference & Prose Summary","d":"Reading","v":"aXAEeeyaeuo"},{"t":"📝 Quiz: Reading","d":"5 questions","isQuiz":true,"quizId":"mod2"}]},{"title":"Module 3: Listening","icon":"🎧","meta":"3 lessons","lessons":[{"t":"3.1 Lectures & Conversations: What to Expect","d":"Reading","v":"EXAbraAOdBQ"},{"t":"3.2 Note-Taking Systems & Attitude/Function Questions","d":"Reading","v":"il_l3WGEZho"},{"t":"📝 Quiz: Listening","d":"5 questions","isQuiz":true,"quizId":"mod3"}]},{"title":"Module 4: Speaking","icon":"🗣️","meta":"3 lessons","lessons":[{"t":"4.1 The Independent Task: Templates & Timing","d":"Reading","v":"RUfPjA7UODU"},{"t":"4.2 The Integrated Tasks: Read, Listen, Speak","d":"Reading","v":"C4J96Q-JzwM"},{"t":"🛠️ Project: Record a 45-Second Independent Response","d":"Project","isProject":true,"v":"RUfPjA7UODU"},{"t":"📝 Quiz: Speaking","d":"5 questions","isQuiz":true,"quizId":"mod4"}]},{"title":"Module 5: Writing","icon":"✍️","meta":"3 lessons","lessons":[{"t":"5.1 The Integrated Writing Task","d":"Reading","v":"KvBauox4auk"},{"t":"5.2 The Academic Discussion Task","d":"Reading","v":"QL4r78VQq1M"},{"t":"📝 Quiz: Writing","d":"5 questions","isQuiz":true,"quizId":"mod5"}]},{"title":"Module 6: Vocabulary, Full Practice & Your Score Plan","lessons":[{"t":"6.1 Academic Vocabulary: The Words Every Section Uses","d":"Video + notes","v":"fE0W18Yz9hM"},{"t":"6.2 Speaking & Writing Vocabulary That Scores 30/30","d":"Video + notes","v":"nMfDRilzxGw"},{"t":"6.3 Full-Length Practice Test: Walkthrough & Review","d":"Video + notes","v":"oygHNmHfaIk"},{"t":"6.4 Your One-Month Study Plan & Test-Day Success","d":"Video + notes","v":"_URwZza44rA"},{"t":"📝 Quiz: Vocabulary & Test Strategy","d":"8 questions","isQuiz":true,"quizId":"mod6"},{"t":"🏆 Final Assessment & Certificate","d":"Assessment","isQuiz":true,"quizId":"final","isFinal":true}],"icon":"🎓","meta":"6 lessons"}]};
COURSES_DB['sat'] = {"id":"sat","title":"Digital SAT Masterclass: Reading & Writing + Math","shortDesc":"A full Digital SAT preparation course covering the adaptive format and 400–1600 scoring, the Reading & Writing section, the Math section, and a proven pacing and strategy system.","category":"Exam Preparation","icon":"📐","gradient":"linear-gradient(135deg,#14532d,#15803d,#22c55e)","instructor":"Samuel Tolbert","instructorTitle":"Founder & CEO, Tolbert Innovation Hub","instructorBio":"Samuel Tolbert founded TIH to bring world-class exam preparation to Liberia and West Africa, guiding students toward the SAT scores that unlock US university admission and scholarships.","rating":4.9,"reviewCount":274,"students":"700+","duration":"38h","level":"Intermediate → Advanced","price":"$25","origPrice":"$160","isFree":false,"badge":"premium","certId":"TIH-2026-SAT-0001","learn":["Understand the Digital SAT’s adaptive format and the 400–1600 score","Master Reading & Writing: craft, structure, expression and Standard English conventions","Solve Math faster: Algebra, Advanced Math, Problem-Solving & Data, and Geometry","Use the built-in Desmos calculator and reference sheet effectively","Apply pacing strategies for the two adaptive modules per section","Attempt a full-length practice set with worked solutions"],"requirements":["Solid basic English and math (roughly high-school level) to build on","A device to practise on Bluebook-style questions when possible","Discipline to practise under timed conditions"],"about":["The SAT is a key admission and scholarship test for universities in the United States. The exam is now the Digital SAT, shorter, adaptive, and taken on a computer through the Bluebook app.","This masterclass explains the new adaptive format, then teaches the content and question strategies for both the Reading & Writing section and the Math section, with worked examples throughout.","Every lesson is written clearly for learners in Liberia and West Africa who are aiming for competitive scores and international opportunities."],"modules":[{"title":"Module 1: The Digital SAT & How It Is Scored","icon":"🧭","meta":"3 lessons","lessons":[{"t":"1.1 The Digital SAT Format: Adaptive Modules & Bluebook","d":"Reading","v":"2aiVO9FoGg4"},{"t":"1.2 Scoring 400–1600 & Setting Your Target","d":"Reading","v":"HXP17Be8TRY"},{"t":"📝 Quiz: Digital SAT Format","d":"5 questions","isQuiz":true,"quizId":"mod1"}]},{"title":"Module 2: Reading & Writing, Reading Skills","icon":"📖","meta":"3 lessons","lessons":[{"t":"2.1 Craft & Structure: Main Idea, Purpose & Vocabulary","d":"Reading","v":"Pw5uTD3_FKw"},{"t":"2.2 Information & Ideas: Evidence, Inference & Data","d":"Reading","v":"POcYofMngBw"},{"t":"📝 Quiz: Reading Skills","d":"5 questions","isQuiz":true,"quizId":"mod2"}]},{"title":"Module 3: Reading & Writing, Writing Skills","icon":"✍️","meta":"3 lessons","lessons":[{"t":"3.1 Standard English Conventions: Grammar & Punctuation","d":"Reading","v":"4jgnbFnXiYs"},{"t":"3.2 Expression of Ideas: Transitions & Rhetorical Synthesis","d":"Reading","v":"lo7LFbac_9o"},{"t":"📝 Quiz: Writing Skills","d":"5 questions","isQuiz":true,"quizId":"mod3"}]},{"title":"Module 4: Math","icon":"🔢","meta":"4 lessons","lessons":[{"t":"4.1 Algebra: Linear Equations, Systems & Inequalities","d":"Reading","v":"vrPbC9fao6Y"},{"t":"4.2 Advanced Math: Quadratics, Exponents & Functions","d":"Reading","v":"zvczFfWx40k"},{"t":"4.3 Problem-Solving, Data Analysis & Geometry","d":"Reading","v":"i0bBokmVtWw"},{"t":"🛠️ Project: Solve a Mixed Math Set with the Desmos Calculator","d":"Project","isProject":true,"v":"vrPbC9fao6Y"},{"t":"📝 Quiz: Math","d":"5 questions","isQuiz":true,"quizId":"mod4"}]},{"title":"Module 5: Strategy & Full Practice","icon":"🏁","meta":"3 lessons","lessons":[{"t":"5.1 Pacing, Guessing & the Adaptive Second Module","d":"Reading","v":"gMGQHSUFRCU"},{"t":"5.2 Test-Day Plan & Score-Boosting Habits","d":"Reading","v":"XKu4sgpHWN8"},{"t":"📝 Quiz: Strategy & Practice","d":"5 questions","isQuiz":true,"quizId":"mod5"}]},{"title":"Module 6: Advanced Drills, Mock Tests & Beyond the SAT","lessons":[{"t":"6.1 Advanced Math: Conquering the Hardest Questions","d":"Video + notes","v":"yqcyspQ6HSg"},{"t":"6.2 Hard Reading & Writing: Beating the Toughest Items","d":"Video + notes","v":"IhWiMWq3VhE"},{"t":"6.3 Bluebook Practice Tests: Take & Review Like a Top Scorer","d":"Video + notes","v":"bUVI0iK740o"},{"t":"6.4 After the SAT: Superscoring, Score Choice & Applications","d":"Video + notes","v":"MUcULumd2hM"},{"t":"📝 Quiz: Advanced Strategy & Next Steps","d":"8 questions","isQuiz":true,"quizId":"mod6"},{"t":"🏆 Final Assessment & Certificate","d":"Assessment","isQuiz":true,"quizId":"final","isFinal":true}],"icon":"🎓","meta":"6 lessons"}]};
COURSES_DB['bible-ot'] = {"id":"bible-ot","title":"Old Testament Survey: God's Promise Unfolding","shortDesc":"Journey through the entire Old Testament, creation and the patriarchs, the exodus and the Law, the kings and prophets, exile and return, and see how it all points to Christ.","category":"TIH Bible School","icon":"📜","gradient":"linear-gradient(135deg,#E31E24,#0B1F3A)","instructor":"TIH Bible School","instructorTitle":"Biblical Studies Faculty","instructorBio":"The TIH Bible School equips learners across Liberia with clear, Bible-centered teaching for a growing faith and a life of service.","rating":4.9,"reviewCount":96,"students":480,"duration":"6 weeks","level":"Beginner","price":"$3","origPrice":"$10","isFree":false,"badge":"new","certId":"TIH-2026-BIB-OT01","learn":["Understand the structure and storyline of all 39 Old Testament books","Explain key events: creation, the Fall, the exodus, the kingdom, and the exile","Know the major covenants God made with His people","Understand the message of the Law, wisdom books, and prophets","See how the Old Testament points forward to Jesus Christ","Read and apply the Old Testament wisely today"],"requirements":["No prior Bible knowledge required","A Bible (print or app) is helpful","Curiosity about the Scriptures"],"about":"This survey takes you through the entire Old Testament in six modules, from the creation and the patriarchs, through the exodus and the giving of the Law, into the era of judges, kings, and prophets, and finally the exile and return. Along the way you will grasp the big storyline, meet the major figures, understand the covenants, and discover how the whole Old Testament prepares the way for Jesus. Perfect for anyone who wants to read the first two-thirds of the Bible with understanding and confidence.","modules":[{"title":"Module 1: The Law (Torah)","icon":"📜","meta":"4 lessons","lessons":[{"t":"1.1 The Old Testament: One Story in 39 Books","d":"12:00","v":"ALsluAKBZ-c"},{"t":"1.2 Genesis: Creation, Fall, and Promise","d":"12:00","v":"GQI72THyO5I"},{"t":"1.3 The Patriarchs & The Exodus","d":"12:00","v":"F4isSyennFo"},{"t":"📝 Quiz: The Law","d":"10 questions","isQuiz":true,"quizId":"mod1"}]},{"title":"Module 2: Israel in the Land","icon":"🏔️","meta":"4 lessons","lessons":[{"t":"2.1 Exodus: Rescue, Passover, and the Law","d":"12:00","v":"jH_aojNJM3E"},{"t":"2.2 Wilderness and the Edge of the Promised Land","d":"12:00","v":"tp5MIrMZFqo"},{"t":"2.3 Conquest and the Judges","d":"12:00","v":"JqOqJlFF_eU"},{"t":"📝 Quiz: Israel in the Land","d":"10 questions","isQuiz":true,"quizId":"mod2"}]},{"title":"Module 3: Wisdom & Worship","icon":"🎵","meta":"4 lessons","lessons":[{"t":"3.1 Job and the Question of Suffering","d":"12:00","v":"xQwnH8th_fs"},{"t":"3.2 The Psalms: Prayers and Songs","d":"12:00","v":"e5LBsYy_4EM"},{"t":"3.3 Proverbs and the Wisdom Books","d":"12:00","v":"AzmYV8GNAIM"},{"t":"🛠️ Project: A Psalm of Your Own","d":"Project","isProject":true}]},{"title":"Module 4: Kings and Prophets","icon":"👑","meta":"4 lessons","lessons":[{"t":"4.1 The Kings: David, Solomon, and a Divided Nation","d":"12:00","v":"QJOju5Dw0V0"},{"t":"4.2 The Major Prophets","d":"12:00","v":"d0A6Uchb1F8"},{"t":"4.3 The Minor Prophets","d":"12:00","v":"qjbYnCadoGw"},{"t":"📝 Quiz: Kings and Prophets","d":"10 questions","isQuiz":true,"quizId":"mod4"}]},{"title":"Module 5: Exile and Return","icon":"🕯️","meta":"4 lessons","lessons":[{"t":"5.1 Exile: When the Nation Fell","d":"12:00","v":"FwZejz71UrA"},{"t":"5.2 Return and Rebuilding: Ezra, Nehemiah","d":"12:00","v":"MkETkRv9tG8"},{"t":"5.3 Esther and the Hidden Hand of God","d":"12:00","v":"JydNSlufRIs"},{"t":"📝 Quiz: Exile and Return","d":"10 questions","isQuiz":true,"quizId":"mod5"}]},{"title":"Module 6: Themes & Christ in the OT","icon":"✡️","meta":"4 lessons","lessons":[{"t":"6.1 The Covenants: God's Unfolding Plan","d":"12:00","v":"6HjlGvl8ljM"},{"t":"6.2 Christ in the Old Testament","d":"12:00","v":"QxOeq3of3O4"},{"t":"6.3 Reading the Old Testament Today","d":"12:00","v":"ak06MSETeo4"},{"t":"🏆 Final Assessment & Certificate","d":"20 questions","isQuiz":true,"quizId":"final","isFinal":true}]}],"reviews":[{"name":"Joseph W.","rating":5,"text":"The Old Testament finally makes sense as one story. I loved seeing how it all points to Jesus."},{"name":"Ruth D.","rating":5,"text":"Clear, well-organized, and easy to understand. The maps of the storyline helped so much."},{"name":"Prince G.","rating":4,"text":"Excellent survey. The quizzes made me actually remember the books and their order."}],"faqs":[{"q":"Is this course hard if I have never read the Old Testament?","a":"No. It is designed for beginners and explains everything clearly, pointing you to the verses so you can read along."},{"q":"Do I need to read all 39 books first?","a":"No. This survey guides you through the big picture; you can read the books alongside or after the course."},{"q":"Will I get a certificate?","a":"Yes. Complete all modules and pass the final assessment (70%) to earn your TIH Bible School certificate."}]};
COURSES_DB['bible-nt'] = {"id":"bible-nt","title":"New Testament Survey: The Good News of Jesus","shortDesc":"Journey through the entire New Testament, the four Gospels, the birth of the Church in Acts, the letters of Paul and others, and the hope of Revelation, and meet Jesus, the Savior of the world.","category":"TIH Bible School","icon":"✝️","gradient":"linear-gradient(135deg,#1565D8,#0B1F3A)","instructor":"TIH Bible School","instructorTitle":"Biblical Studies Faculty","instructorBio":"The TIH Bible School equips learners across Liberia with clear, Bible-centered teaching for a growing faith and a life of service.","rating":4.9,"reviewCount":112,"students":560,"duration":"6 weeks","level":"Beginner","price":"$3","origPrice":"$10","isFree":false,"badge":"new","certId":"TIH-2026-BIB-NT01","learn":["Understand the structure and storyline of all 27 New Testament books","Know the life, teaching, death, and resurrection of Jesus from the four Gospels","Explain the gospel and how a person is saved","Trace the birth and growth of the early Church in Acts","Understand the main themes of Paul's and the general letters","Grasp the hope of Revelation and how the whole Bible fits together"],"requirements":["No prior Bible knowledge required","A Bible (print or app) is helpful","An open and curious heart"],"about":"This survey walks you through the entire New Testament in six modules, beginning with the life of Jesus in the four Gospels, moving to the gospel message and the birth of the Church in Acts, then through the letters of Paul and other apostles, and finishing with the hope of Revelation and the big picture of the whole Bible. You will come to know Jesus, who He is and what He has done, and understand how to live as His follower. Ideal for new believers, seekers, and anyone wanting to read the New Testament with clarity and confidence.","modules":[{"title":"Module 1: The Life of Jesus (Part 1)","icon":"⭐","meta":"4 lessons","lessons":[{"t":"1.1 The New Testament: The Story of Jesus and His Church","d":"12:00","v":"Q0BrP8bqj0c"},{"t":"1.2 The Four Gospels: Four Portraits of Jesus","d":"12:00","v":"3Dv4-n6OYGI"},{"t":"1.3 The Birth and Early Life of Jesus","d":"12:00","v":"XIb_dCIxzr0"},{"t":"📝 Quiz: The Life of Jesus (Part 1)","d":"10 questions","isQuiz":true,"quizId":"mod1"}]},{"title":"Module 2: The Life of Jesus (Part 2)","icon":"✝️","meta":"4 lessons","lessons":[{"t":"2.1 Jesus' Teaching: The Kingdom & Sermon on the Mount","d":"12:00","v":"B0O525zOstQ"},{"t":"2.2 Parables and Miracles","d":"12:00","v":"XIb_dCIxzr0"},{"t":"2.3 The Death and Resurrection of Jesus","d":"12:00","v":"G_OlRWGLdnw"},{"t":"📝 Quiz: The Life of Jesus (Part 2)","d":"10 questions","isQuiz":true,"quizId":"mod2"}]},{"title":"Module 3: Who Is Jesus & the Gospel","icon":"🕊️","meta":"4 lessons","lessons":[{"t":"3.1 Who Is Jesus? The Heart of the New Testament","d":"12:00","v":"CGbNw855ksw"},{"t":"3.2 The Gospel Message and How to Respond","d":"12:00","v":"Kq3-bwr25j4"},{"t":"3.3 The Reliability of the New Testament","d":"12:00","v":"ej_6dVdJSIU"},{"t":"🛠️ Project: Share the Story of Jesus","d":"Project","isProject":true}]},{"title":"Module 4: The Early Church and Paul","icon":"🔥","meta":"4 lessons","lessons":[{"t":"4.1 The Birth of the Church: Acts and Pentecost","d":"12:00","v":"lXF2nBEkgUE"},{"t":"4.2 The Gospel Spreads: Persecution and Mission","d":"12:00","v":"CGbNw855ksw"},{"t":"4.3 Paul's Letters to the Churches","d":"12:00","v":"5nvVVcYD-0w"},{"t":"📝 Quiz: The Early Church and Paul","d":"10 questions","isQuiz":true,"quizId":"mod4"}]},{"title":"Module 5: The Letters and Revelation","icon":"📨","meta":"4 lessons","lessons":[{"t":"5.1 Living the Christian Life: The General Letters","d":"12:00","v":"7_CGP-12AE0"},{"t":"5.2 The Church as God's Family and Body","d":"12:00","v":"ak06MSETeo4"},{"t":"5.3 Hope and Victory: The Book of Revelation","d":"12:00","v":"ak06MSETeo4"},{"t":"📝 Quiz: The Letters and Revelation","d":"10 questions","isQuiz":true,"quizId":"mod5"}]},{"title":"Module 6: The Whole Story & Next Steps","icon":"🌍","meta":"4 lessons","lessons":[{"t":"6.1 The Whole Story: How the Bible Fits Together","d":"12:00","v":"QxOeq3of3O4"},{"t":"6.2 Applying the New Testament to Your Life","d":"12:00","v":"B0O525zOstQ"},{"t":"6.3 Continuing to Grow: Your Next Steps","d":"12:00","v":"Q0BrP8bqj0c"},{"t":"🏆 Final Assessment & Certificate","d":"20 questions","isQuiz":true,"quizId":"final","isFinal":true}]}],"reviews":[{"name":"Mercy K.","rating":5,"text":"I have read the Gospels before, but now I finally understand how the whole New Testament fits together. Beautiful course."},{"name":"Daniel S.","rating":5,"text":"Clear, Christ-centered, and easy to follow. The section on Paul's letters was so helpful."},{"name":"Blessing T.","rating":5,"text":"This course helped me understand the gospel and share it with my family. Thank you TIH Bible School!"}],"faqs":[{"q":"Do I need to have read the New Testament before taking this?","a":"No. This survey is written for beginners and explains everything clearly, pointing you to the verses so you can read along."},{"q":"Is this course only for Christians?","a":"Not at all. Seekers with honest questions are very welcome. The course explains who Jesus is and invites you to consider the good news."},{"q":"Will I get a certificate?","a":"Yes. Complete all modules and pass the final assessment (70%) to earn your TIH Bible School certificate."}]};
COURSES_DB['bible-foundations'] = {"id":"bible-foundations","title":"Christian Foundations & Discipleship: Building a Life on the Word","shortDesc":"A complete beginner's guide to the Christian faith, who God is, the gospel of Jesus, salvation, prayer, the Holy Spirit, the Church, and how to grow as a disciple.","category":"TIH Bible School","icon":"🕊️","gradient":"linear-gradient(135deg,#1565D8,#0B1F3A)","instructor":"TIH Bible School","instructorTitle":"Discipleship Faculty","instructorBio":"The TIH Bible School equips learners across Liberia with clear, Bible-centered teaching for a growing faith and a life of service.","rating":4.9,"reviewCount":128,"students":640,"duration":"6 weeks","level":"Beginner","price":"$3","origPrice":"$10","isFree":false,"badge":"new","certId":"TIH-2026-BIB-CF01","learn":["Understand who God is and the doctrine of the Trinity","Explain the gospel: sin, the cross, the resurrection, and salvation by grace","Know what it means to be born again and have assurance of salvation","Build daily habits of prayer and Bible reading","Understand the Holy Spirit and grow the fruit of the Spirit","Live and share your faith as a committed disciple of Jesus"],"requirements":["No prior Bible knowledge required","A Bible (print or app) is helpful","An open heart and willingness to learn"],"about":"This course lays a solid, Bible-based foundation for anyone exploring or beginning the Christian faith. Over six modules you will move from knowing who God is, through the gospel of Jesus Christ and the meaning of salvation, into the practical habits of prayer, Scripture, church life, and mission. Whether you are a brand-new believer, a seeker with questions, or someone wanting to refresh the basics, this course will ground you in the essentials and set you on a path of lifelong growth as a disciple of Jesus.","modules":[{"title":"Module 1: Knowing God","icon":"📖","meta":"4 lessons","lessons":[{"t":"1.1 Who Is God? Knowing the One We Worship","d":"12:00","v":"eAvYmE2YYIU"},{"t":"1.2 The Trinity: One God, Three Persons","d":"12:00","v":"eAvYmE2YYIU"},{"t":"1.3 The Bible: God's Word to Us","d":"12:00","v":"ak06MSETeo4"},{"t":"📝 Quiz: Knowing God","d":"10 questions","isQuiz":true,"quizId":"mod1"}]},{"title":"Module 2: The Human Problem and God's Rescue","icon":"✝️","meta":"4 lessons","lessons":[{"t":"2.1 Created in God's Image, and the Problem of Sin","d":"12:00","v":"GQI72THyO5I"},{"t":"2.2 Jesus Christ: Fully God, Fully Man","d":"12:00","v":"QxOeq3of3O4"},{"t":"2.3 The Cross and the Resurrection","d":"12:00","v":"G_OlRWGLdnw"},{"t":"📝 Quiz: The Human Problem and God's Rescue","d":"10 questions","isQuiz":true,"quizId":"mod2"}]},{"title":"Module 3: Salvation and New Life","icon":"🕊️","meta":"4 lessons","lessons":[{"t":"3.1 Grace, Faith, and Salvation","d":"12:00","v":"B0O525zOstQ"},{"t":"3.2 The New Birth: Becoming a Child of God","d":"12:00","v":"Kq3-bwr25j4"},{"t":"3.3 Assurance: How Can I Know I Am Saved?","d":"12:00","v":"7_CGP-12AE0"},{"t":"🛠️ Project: Write Your Testimony","d":"Project","isProject":true}]},{"title":"Module 4: Walking with God","icon":"🙏","meta":"4 lessons","lessons":[{"t":"4.1 Prayer: Talking with Your Father","d":"12:00","v":"3Dv4-n6OYGI"},{"t":"4.2 The Holy Spirit and the Fruit He Grows","d":"12:00","v":"Kq3-bwr25j4"},{"t":"4.3 Reading and Obeying God's Word","d":"12:00","v":"ak06MSETeo4"},{"t":"📝 Quiz: Walking with God","d":"10 questions","isQuiz":true,"quizId":"mod4"}]},{"title":"Module 5: The Church and the Christian Life","icon":"⛪","meta":"4 lessons","lessons":[{"t":"5.1 The Church: God's Family and Community","d":"12:00","v":"7_CGP-12AE0"},{"t":"5.2 Living as a Disciple: Holiness and Everyday Faith","d":"12:00","v":"B0O525zOstQ"},{"t":"5.3 The Church's Ordinances in Practice","d":"12:00","v":"G_OlRWGLdnw"},{"t":"📝 Quiz: The Church and the Christian Life","d":"10 questions","isQuiz":true,"quizId":"mod5"}]},{"title":"Module 6: Mission, Hope, and Next Steps","icon":"🌍","meta":"4 lessons","lessons":[{"t":"6.1 Sharing Your Faith and the Great Commission","d":"12:00","v":"B0O525zOstQ"},{"t":"6.2 Hope for the Future: Christ's Return and Eternity","d":"12:00","v":"Zy2AQlK6C5k"},{"t":"6.3 Next Steps: Growing for a Lifetime","d":"12:00","v":"ak06MSETeo4"},{"t":"🏆 Final Assessment & Certificate","d":"20 questions","isQuiz":true,"quizId":"final","isFinal":true}]}],"reviews":[{"name":"Grace M.","rating":5,"text":"Clear and easy to follow. I finally understand the gospel and how to pray. Thank you TIH!"},{"name":"Emmanuel T.","rating":5,"text":"As a new believer this gave me exactly the foundation I needed. The quizzes helped me remember."},{"name":"Fatu K.","rating":5,"text":"Every lesson points to Scripture. I feel more confident sharing my faith now."}],"faqs":[{"q":"Do I need to be a Christian to take this course?","a":"No. This course is perfect for seekers with questions as well as new believers. Come as you are and explore the faith honestly."},{"q":"Do I need to know the Bible already?","a":"Not at all. Every lesson explains the Scriptures clearly and points you to the verses so you can read them yourself."},{"q":"Will I get a certificate?","a":"Yes. Complete all modules and pass the final assessment (70%) to earn your TIH Bible School certificate."}]};
COURSES_DB['accounting-bookkeeping'] = {"id":"accounting-bookkeeping","title":"Accounting and Bookkeeping","shortDesc":"Learn practical bookkeeping, accounting basics, financial records, receipts, invoices, cashbooks, bank reconciliation, and simple reports for small businesses, NGOs, churches, and personal finance.","category":"Business & Finance","icon":"🧾","gradient":"linear-gradient(135deg,#064e3b,#0f766e)","instructor":"Samuel Tolbert","instructorTitle":"Founder & CEO, Tolbert Innovation Hub","instructorBio":"Samuel Tolbert leads TIH programs that help learners build practical business, digital, and professional skills for real work opportunities across Liberia and West Africa.","rating":4.9,"reviewCount":218,"students":"1,200+","duration":"30h","level":"Beginner","price":"$5","origPrice":"$85","badge":"new","certId":"TIH-2026-ACB-0001","learn":["Explain the difference between bookkeeping and accounting","Record income, expenses, assets, liabilities, and equity correctly","Prepare receipts, invoices, payment vouchers, and simple ledgers","Maintain a cashbook and petty cash record for a small organization","Reconcile cash and bank balances with statements and receipts","Prepare simple profit and loss, balance sheet, and cash flow reports","Use basic Excel or Google Sheets formulas for bookkeeping","Build a simple bookkeeping system for a small business, NGO, church, or personal budget"],"requirements":["No accounting experience required, this course starts from the basics","A notebook, calculator, and phone or computer for practice","Basic reading and arithmetic skills","Willingness to practice with sample receipts, invoices, and cashbook exercises"],"about":["Accounting and bookkeeping are essential skills for every business, NGO, church, school, and household. When records are clear, leaders can make better decisions, avoid waste, prepare for taxes, and build trust with customers, donors, and partners.","This beginner-friendly course teaches practical record keeping from the ground up. You will learn how money enters and leaves an organization, how to organize documents, how to maintain books, and how to prepare simple reports that explain financial performance.","The course is designed for Liberian learners, entrepreneurs, office assistants, nonprofit workers, church administrators, students, and anyone who wants to manage money with confidence and accountability."],"modules":[{"title":"Module 1: Foundations of Accounting and Bookkeeping","icon":"📘","meta":"5 lessons","lessons":[{"t":"1.1 What Accounting and Bookkeeping Mean","d":"Reading + notes"},{"t":"1.2 Users of Financial Information","d":"Reading + notes"},{"t":"1.3 The Accounting Equation","d":"Practice"},{"t":"1.4 Source Documents and Record Keeping","d":"Practice"},{"t":"📝 Quiz: Accounting Foundations","d":"5 questions","isQuiz":true,"quizId":"mod1"}]},{"title":"Module 2: Recording Business Transactions","icon":"🧮","meta":"5 lessons","lessons":[{"t":"2.1 Income, Expenses, Assets, Liabilities, and Equity","d":"Reading + notes"},{"t":"2.2 Debit and Credit Basics","d":"Practice"},{"t":"2.3 Journals and Ledgers","d":"Practice"},{"t":"2.4 Common Small Business Transactions","d":"Case study"},{"t":"📝 Quiz: Recording Transactions","d":"5 questions","isQuiz":true,"quizId":"mod2"}]},{"title":"Module 3: Cashbook, Petty Cash, and Banking","icon":"💵","meta":"5 lessons","lessons":[{"t":"3.1 Cash Receipts and Cash Payments","d":"Practice"},{"t":"3.2 Maintaining a Simple Cashbook","d":"Practice"},{"t":"3.3 Petty Cash and Imprest System","d":"Practice"},{"t":"3.4 Bank Reconciliation Basics","d":"Practice"},{"t":"📝 Quiz: Cash and Bank Records","d":"5 questions","isQuiz":true,"quizId":"mod3"}]},{"title":"Module 4: Sales, Purchases, Inventory, and Payroll","icon":"🛒","meta":"5 lessons","lessons":[{"t":"4.1 Creating Invoices and Receipts","d":"Practice"},{"t":"4.2 Recording Purchases and Supplier Payments","d":"Practice"},{"t":"4.3 Basic Inventory Records","d":"Practice"},{"t":"4.4 Simple Payroll and Staff Payment Records","d":"Case study"},{"t":"📝 Quiz: Sales, Purchases, and Payroll","d":"5 questions","isQuiz":true,"quizId":"mod4"}]},{"title":"Module 5: Financial Reports and Decision Making","icon":"📊","meta":"5 lessons","lessons":[{"t":"5.1 Trial Balance and Error Checking","d":"Practice"},{"t":"5.2 Profit and Loss Statement","d":"Practice"},{"t":"5.3 Balance Sheet Basics","d":"Practice"},{"t":"5.4 Cash Flow and Budget Reports","d":"Practice"},{"t":"📝 Quiz: Financial Reports","d":"5 questions","isQuiz":true,"quizId":"mod5"}]},{"title":"Module 6: Digital Bookkeeping and Capstone Project","icon":"💻","meta":"5 lessons","lessons":[{"t":"6.1 Bookkeeping with Excel or Google Sheets","d":"Practice"},{"t":"6.2 Building a Simple Monthly Bookkeeping Template","d":"Project"},{"t":"6.3 Controls, Ethics, and Preventing Fraud","d":"Reading + notes"},{"t":"🛠️ Capstone: Create a One-Month Bookkeeping File","d":"Project","isProject":true},{"t":"🏆 Final Assessment and Certificate","d":"10 questions","isQuiz":true,"quizId":"final","isFinal":true}]}],"reviews":[{"name":"Martha K.","rating":5,"text":"This course made bookkeeping simple. I can now organize receipts and prepare a clean cashbook for our small business."},{"name":"Joseph T.","rating":5,"text":"The examples are practical for Liberia. I finally understand income, expenses, cashbook, and bank reconciliation."},{"name":"Rebecca S.","rating":5,"text":"Very helpful for NGO and church record keeping. The capstone gave me a template I can keep using."}],"faqs":[{"q":"Do I need accounting experience?","a":"No. This course starts with the basics and uses simple examples."},{"q":"Will I learn Excel bookkeeping?","a":"Yes. The final module guides you to build a simple bookkeeping template in Excel or Google Sheets."},{"q":"Will I get a certificate?","a":"Yes. Complete the lessons, quizzes, and final assessment to earn a verifiable TIH Professional Certificate."}]};
